const state={route:'home',settings:{},projects:[],sync:null,currentProject:null,studyTab:'home',aiStatus:null,aiThread:null};
const view=document.querySelector('#view');
const titleEl=document.querySelector('#title');
const crumbEl=document.querySelector('#crumb');
const modal=document.querySelector('#modal');
let navigationId=0;

const esc=(value='')=>String(value).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const val=selector=>document.querySelector(selector)?.value?.trim()||'';
const bool=selector=>Boolean(document.querySelector(selector)?.checked);
const fmtBytes=n=>{n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(1)} GB`};
const fmtDate=value=>{if(!value)return 'Nunca';try{return new Date(value).toLocaleString('es-PE',{dateStyle:'medium',timeStyle:'short'})}catch{return value}};
const sourceStatusLabel=status=>({updated:'Actualizado',ok:'Disponible',ready:'Disponible',running:'Sincronizando',pending:'Pendiente',error:'No disponible'}[String(status||'').toLowerCase()]||'Pendiente');
const friendlyConnectionError=message=>!message?'':(/WinError|socket|fetch|connect|network|timed?\s*out|timeout/i.test(String(message))?'No se pudo conectar en este momento. Se conserva la última copia válida; puedes volver a intentarlo más tarde.':String(message));
function showSelectedFile(input){const label=document.querySelector(`#${input.id}Name`);if(label)label.textContent=input.files?.[0]?.name||'Ningún archivo seleccionado'}
const visibleTranslations=[
  ['Dimitry AI','Dimitry IA'],['Game Modification','Modificación de juegos'],['GAME LAB','TALLER DE JUEGOS'],
  ['Palworld Wiki','Guía Palworld'],['PALWORLD WIKI','GUÍA PALWORLD'],['PALWORLD CENTER','CENTRO PALWORLD'],
  ['Investigación web','Investigación en internet'],['investigación web','investigación en internet'],
  ['búsqueda web','búsqueda en internet'],['páginas web','páginas de internet'],['Editor de saves','Editor de partidas'],
  ['administrar saves','administrar partidas guardadas'],['los saves','las partidas guardadas'],['tu save','tu partida guardada'],
  ['save antiguo','partida antigua'],['dumps','volcados'],['dump','volcado'],['endpoint','servicio'],
  ['Endpoint','Servicio'],['Los saves','Las partidas guardadas'],['Estado de inteligencia','Estado de la IA'],
  ['Modo Pro','Modo avanzado'],['Obsidian Gold','Oro obsidiana'],['Arcane Royal','Realeza arcana'],
  ['Midnight Modern','Medianoche moderna'],['Console Pop','Consola alegre'],['Rounded Play','Consola redondeada'],
  ['PIXEL ARCADE','PÍXEL CLÁSICO'],['Study Pro','Estudio profesional'],['Retro para títulos','Estilo clásico para títulos'],['premium','distinguido'],
  ['Fantasia','Fantasía'],['Gaming','Juegos'],['Revisa scripts','Revisa archivos Lua'],['Crear script para GameGuardian','Crear archivo Lua para GameGuardian'],
  ['Script Lua creado','Archivo Lua creado'],['anticheat','sistemas contra trampas'],
  ['OpenAI Chat Completions','conversaciones de OpenAI'],['URL BASE','DIRECCIÓN BASE']
];
function translateVisible(value){let result=String(value||'');for(const [from,to] of visibleTranslations)result=result.split(from).join(to);return result}
function localizeInterface(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{const translated=translateVisible(node.nodeValue);if(translated!==node.nodeValue)node.nodeValue=translated});
  root.querySelectorAll?.('[placeholder],[title],[aria-label]').forEach(node=>['placeholder','title','aria-label'].forEach(attribute=>{if(node.hasAttribute(attribute)){const current=node.getAttribute(attribute),translated=translateVisible(current);if(translated!==current)node.setAttribute(attribute,translated)}}));
  enhanceInterface();
}
let localizationQueued=false;
new MutationObserver(()=>{if(localizationQueued)return;localizationQueued=true;queueMicrotask(()=>{localizationQueued=false;localizeInterface()})}).observe(document.body,{childList:true,subtree:true});

let soundContext=null;
const soundEnabled=()=>localStorage.getItem('dimitryInterfaceSounds')!=='0';
function playUiSound(kind='move'){
  if(!soundEnabled())return;
  try{
    soundContext=soundContext||new (window.AudioContext||window.webkitAudioContext)();
    if(soundContext.state==='suspended')soundContext.resume();
    const patterns={move:[[440,0,.045],[660,.035,.075]],confirm:[[523,0,.06],[784,.055,.13]],success:[[523,0,.055],[659,.045,.1],[988,.1,.18]],warning:[[260,0,.08],[190,.07,.15]]};
    const now=soundContext.currentTime;(patterns[kind]||patterns.move).forEach(([frequency,delay,duration],index)=>{const oscillator=soundContext.createOscillator(),gain=soundContext.createGain();oscillator.type=index%2?'triangle':'sine';oscillator.frequency.setValueAtTime(frequency,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.035,now+delay+.008);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+duration);oscillator.connect(gain).connect(soundContext.destination);oscillator.start(now+delay);oscillator.stop(now+delay+duration+.02)});
  }catch{}
}
function enhanceInterface(){
  document.querySelectorAll('input[type="file"]:not(.file-input):not([hidden])').forEach((input,index)=>{input.id=input.id||`archivoSeleccionado${index}`;input.classList.add('file-input');const wrapper=document.createElement('div');wrapper.className='file-picker';input.parentNode.insertBefore(wrapper,input);wrapper.append(input);wrapper.insertAdjacentHTML('beforeend',`<label class="btn" for="${esc(input.id)}">Seleccionar archivo</label><small id="${esc(input.id)}Name">Ningún archivo seleccionado</small>`);input.addEventListener('change',()=>showSelectedFile(input))});
  const simpleMode=document.querySelector('#simpleMode'),appearance=simpleMode?.closest('article');
  const aiMeta=document.querySelector('#aiChatMeta'),aiModeBadge=document.querySelector('.ai-chat-head .power-badge');if(aiMeta&&state.aiStatus){const modeLabels={local:'Local',cloud:'Nube',automatic:'Automático'};aiMeta.textContent=state.aiStatus.mode==='local'?'Modo local: usa Ollama en esta computadora.':state.aiStatus.mode==='cloud'?'Modo en la nube: usa el proveedor conectado.':'Modo automático: usa la mejor conexión disponible.';if(aiModeBadge)aiModeBadge.innerHTML=`<i></i>${modeLabels[state.aiStatus.mode]||'Automático'}`}
  if(appearance&&!document.querySelector('#experienceControls')){
    const block=document.createElement('div');block.id='experienceControls';block.className='experience-controls';block.innerHTML='<h3>Respuesta de la interfaz</h3><p>Sonidos originales y movimientos suaves para que navegar se sienta más vivo.</p><label class="check"><input id="interfaceSounds" type="checkbox"> Sonidos de botones y avisos</label><label class="check"><input id="interfaceMotion" type="checkbox"> Animaciones y profundidad visual</label>';
    appearance.append(block);
    const sounds=block.querySelector('#interfaceSounds'),motion=block.querySelector('#interfaceMotion');sounds.checked=soundEnabled();motion.checked=document.body.dataset.motion!=='off';
    sounds.onchange=()=>{localStorage.setItem('dimitryInterfaceSounds',sounds.checked?'1':'0');if(sounds.checked)playUiSound('success')};
    motion.onchange=()=>{localStorage.setItem('dimitryInterfaceMotion',motion.checked?'1':'0');document.body.dataset.motion=motion.checked?'on':'off'};
  }
}
const savedMotion=localStorage.getItem('dimitryInterfaceMotion');document.body.dataset.motion=savedMotion==='0'||(savedMotion===null&&window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)?'off':'on';
document.addEventListener('click',event=>{const control=event.target.closest('button,a.btn,label.btn');if(!control||control.matches(':disabled'))return;const kind=control.classList.contains('danger')?'warning':(control.classList.contains('primary')||control.classList.contains('green'))?'confirm':'move';playUiSound(kind)},true);

async function api(url,options={}){
  const response=await fetch(url,options);
  if(!response.ok){let detail=`Error ${response.status}`;try{const data=await response.json();detail=data.detail||detail}catch{}throw new Error(detail)}
  const type=response.headers.get('content-type')||'';
  return type.includes('application/json')?response.json():response;
}
function toast(message,type='ok'){
  const node=document.createElement('div');node.className=`toast ${type}`;node.textContent=message;
  document.querySelector('#toastStack').append(node);if(type==='ok')playUiSound('success');else if(type==='error')playUiSound('warning');setTimeout(()=>node.remove(),4200);
}
function loading(message='Cargando…'){view.innerHTML=`<div class="loading"><div class="spinner"></div>${esc(message)}</div>`}
function setHead(title,crumb){titleEl.textContent=title;crumbEl.textContent=crumb;document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route))}
function openModal(title,body){document.querySelector('#modalTitle').textContent=title;document.querySelector('#modalBody').innerHTML=body;modal.classList.remove('hidden')}
function closeModal(){modal.classList.add('hidden');document.querySelector('#modalBody').innerHTML=''}
function notice(text,type='info'){return `<div class="notice ${type}">${esc(text)}</div>`}
function resultBox(text,extra=''){return `<div class="result">${extra}<pre>${esc(text||'Sin contenido')}</pre></div>`}
function projectOptions(projects){return `<option value="">Sin proyecto asociado</option>${projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}`}

async function navigate(route,options={}){
  const currentNavigation=++navigationId;state.route=route;document.querySelector('#sidebar').classList.remove('open');
  const renderers={home:renderHome,assistant:renderAssistant,study:()=>renderStudy(options.tab||state.studyTab),palworld:()=>renderPalworld('all'),'palworld-wiki':()=>renderPalworld('wiki'),'palworld-editor':()=>renderPalworld('editor'),gamemod:renderGameMod,projects:renderProjects,files:renderFiles,updates:renderUpdates,settings:renderSettings};
  try{await (renderers[route]||renderHome)();if(currentNavigation!==navigationId&&state.route!==route)await navigate(state.route)}catch(error){if(currentNavigation===navigationId)renderFatalError(error,route)}
}

function renderFatalError(error,route=state.route){
  console.error(error);
  setHead('No se pudo abrir esta sección','ERROR RECUPERABLE');
  view.innerHTML=`<section class="panel"><div class="notice bad"><b>Ocurrió un error al mostrar esta página.</b><br>${esc(error?.message||'Error inesperado')}</div><div class="form-actions"><button class="btn primary" id="retryRender">Reintentar</button><button class="btn" id="returnHome">Volver a Inicio</button></div></section>`;
  document.querySelector('#retryRender').onclick=()=>navigate(route);
  document.querySelector('#returnHome').onclick=()=>navigate('home');
}
window.addEventListener('error',event=>renderFatalError(event.error||new Error(event.message)));
window.addEventListener('unhandledrejection',event=>renderFatalError(event.reason instanceof Error?event.reason:new Error(String(event.reason))));

function launchCard(route,icon,title,text,color,tab=''){return `<button class="launch-card ${color}" data-go="${route}" ${tab?`data-tab="${tab}"`:''}><span class="launch-icon">${icon}</span><h3>${esc(title)}</h3><p>${esc(text)}</p></button>`}
function bindLaunch(){document.querySelectorAll('[data-go]').forEach(btn=>btn.onclick=()=>navigate(btn.dataset.go,{tab:btn.dataset.tab||''}))}

