function aiProviderLabel(name){return ({openai:'OpenAI API',ollama:'Ollama local',compatible:'Proveedor compatible',local:'Dimitry Hub local'})[name]||name||'IA'}
function sourcePills(sources=[]){return sources.length?`<div class="chat-sources">${sources.map(item=>item.url?`<a class="source-pill" href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.title||item.url)}</a>`:`<span class="source-pill">▤ ${esc(item.title||'Fuente local')}</span>`).join('')}</div>`:''}
function chatMessages(messages=[]){if(!messages.length)return `<div class="chat-empty"><div class="orb">✦</div><h2>¿En qué trabajamos?</h2><p>Pregunta algo, activa investigación web o elige una biblioteca. La conversación se guarda automáticamente.</p></div>`;return messages.map(m=>`<div class="chat-message ${m.role==='user'?'user':'assistant'}"><div class="chat-avatar">${m.role==='user'?'DV':'✦'}</div><div class="chat-bubble">${esc(m.content)}${m.role==='assistant'?sourcePills(m.sources||[]):''}${m.provider?`<span class="chat-meta">${esc(aiProviderLabel(m.provider))} · ${esc(m.model||'modelo')}</span>`:''}</div></div>`).join('')}
async function renderAssistant(){state.route='assistant';setHead('Dimitry AI','CENTRO DE INTELIGENCIA');loading('Preparando el asistente');try{const [status,threads]=await Promise.all([api('/api/ai/status'),api('/api/ai/threads')]);state.aiStatus=status;const ready=status.providers?.openai?.configured||status.providers?.ollama?.online||status.providers?.compatible?.configured;view.innerHTML=`<section class="ai-layout"><aside class="ai-side"><button class="btn primary" id="newAIThread">＋ Nueva conversación</button><div><label class="field"><span style="font-size:11px;font-weight:1000;color:var(--muted)">ÁREA</span><select id="aiDomain"><option value="general">General</option><option value="research">Investigación académica</option><option value="legal">Derecho peruano</option><option value="palworld">Palworld</option><option value="gamemod">Game Modification</option><option value="libtool">LibTool y Lua</option></select></label></div><div><small style="font-weight:1000;color:var(--muted)">ATAJOS</small><div class="quick-prompts" style="margin-top:8px"><button class="quick-prompt" data-prompt="Investiga este tema y dame un plan de trabajo con fuentes verificables: ">⌕ Investigar un tema</button><button class="quick-prompt" data-prompt="Estructura este contenido como una monografía APA 7: ">M Estructurar monografía</button><button class="quick-prompt" data-prompt="Analiza este problema técnico paso a paso: ">⌘ Analizar código o dump</button><button class="quick-prompt" data-prompt="Explícame esto para mi examen con ejemplos: ">✎ Preparar examen</button></div></div><div><div class="panel-head" style="margin:2px 0 8px"><h3>Conversaciones</h3><small>${threads.threads.length}</small></div><div class="thread-list" id="threadList">${threads.threads.map(t=>`<button class="thread-item ${state.aiThread===t.id?'active':''}" data-thread="${t.id}"><b>${esc(t.title)}</b><small>${esc(t.domain)} · ${t.message_count} mensajes</small></button>`).join('')||'<div class="empty">Aún no hay conversaciones.</div>'}</div></div><div style="margin-top:auto"><span class="power-badge ${ready?'':'off'}"><i></i>${ready?'IA preparada':'Falta configurar IA'}</span><button class="btn small" data-go="settings" style="width:100%;margin-top:9px">Configurar potencia</button></div></aside><section class="ai-chat"><div class="ai-chat-head"><div><h2 id="aiChatTitle">Dimitry AI</h2><p id="aiChatMeta">${ready?'Modo automático: usa la mejor conexión disponible.':'Configura OpenAI API u Ollama para comenzar.'}</p></div><span class="power-badge"><i></i>${esc(status.mode||'automatic')}</span></div><div class="chat-feed" id="chatFeed">${chatMessages([])}</div><div class="chat-composer"><textarea id="aiMessage" placeholder="Escribe lo que necesitas. Puedes pegar texto, preguntas o instrucciones…"></textarea><div class="composer-row"><div class="composer-options"><label class="mini-toggle"><input type="checkbox" id="aiWeb" ${state.settings.ai_web_search_default==='1'?'checked':''}> Investigar en internet</label><label class="mini-toggle"><input type="checkbox" id="aiLibrary" checked> Usar biblioteca local</label></div><button class="btn primary" id="sendAI">Enviar ✦</button></div></div></section></section>`;bindLaunch();document.querySelector('#newAIThread').onclick=()=>{state.aiThread=null;document.querySelector('#chatFeed').innerHTML=chatMessages([]);document.querySelector('#aiChatTitle').textContent='Dimitry AI';document.querySelector('#aiMessage').focus();document.querySelectorAll('.thread-item').forEach(x=>x.classList.remove('active'))};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{document.querySelector('#aiMessage').value=b.dataset.prompt;document.querySelector('#aiMessage').focus()});document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>openAIThread(Number(b.dataset.thread)));document.querySelector('#sendAI').onclick=sendAIMessage;document.querySelector('#aiMessage').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();sendAIMessage()}};if(!ready){document.querySelector('#sendAI').disabled=true;document.querySelector('#aiMessage').disabled=true;document.querySelector('#aiMessage').placeholder='Configura una IA en Ajustes para comenzar.'}if(state.aiThread)await openAIThread(state.aiThread)}catch(error){view.innerHTML=notice(error.message,'bad')}}
async function openAIThread(id){try{const data=await api(`/api/ai/threads/${id}`);state.aiThread=id;document.querySelector('#aiDomain').value=data.thread.domain||'general';document.querySelector('#aiChatTitle').textContent=data.thread.title;document.querySelector('#aiChatMeta').textContent=`${data.messages.length} mensajes guardados`;document.querySelector('#chatFeed').innerHTML=chatMessages(data.messages);document.querySelector('#chatFeed').scrollTop=document.querySelector('#chatFeed').scrollHeight;document.querySelectorAll('.thread-item').forEach(x=>x.classList.toggle('active',Number(x.dataset.thread)===id))}catch(error){toast(error.message,'error')}}
async function sendAIMessage(){const input=document.querySelector('#aiMessage');const message=input?.value.trim();if(!message)return;const send=document.querySelector('#sendAI');send.disabled=true;const feed=document.querySelector('#chatFeed');if(feed.querySelector('.chat-empty'))feed.innerHTML='';feed.insertAdjacentHTML('beforeend',chatMessages([{role:'user',content:message}]));feed.insertAdjacentHTML('beforeend',`<div class="chat-message assistant" id="aiThinking"><div class="chat-avatar">✦</div><div class="chat-bubble"><div class="spinner" style="width:24px;height:24px;border-width:3px;margin:0"></div><span class="chat-meta">Pensando y revisando fuentes…</span></div></div>`);feed.scrollTop=feed.scrollHeight;input.value='';try{const data=await api('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,thread_id:state.aiThread,domain:val('#aiDomain')||'general',web_search:bool('#aiWeb'),include_library:bool('#aiLibrary')})});state.aiThread=data.thread_id;document.querySelector('#aiThinking')?.remove();feed.insertAdjacentHTML('beforeend',chatMessages([{role:'assistant',content:data.response,provider:data.provider,model:data.model,sources:data.sources||[]}])) ;feed.scrollTop=feed.scrollHeight;const threads=await api('/api/ai/threads');document.querySelector('#threadList').innerHTML=threads.threads.map(t=>`<button class="thread-item ${state.aiThread===t.id?'active':''}" data-thread="${t.id}"><b>${esc(t.title)}</b><small>${esc(t.domain)} · ${t.message_count} mensajes</small></button>`).join('');document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>openAIThread(Number(b.dataset.thread)));toast(`Respuesta generada con ${aiProviderLabel(data.provider)}`)}catch(error){document.querySelector('#aiThinking')?.remove();feed.insertAdjacentHTML('beforeend',chatMessages([{role:'assistant',content:`No pude completar la respuesta: ${error.message}`}])) ;toast(error.message,'error')}finally{send.disabled=false;input.focus()}}

function studyTabs(active){return `<div class="tabs"><button class="tab ${active==='home'?'active':''}" data-study="home">Herramientas</button><button class="tab ${active==='monograph'?'active':''}" data-study="monograph">Monografía APA 7</button><button class="tab ${active==='materials'?'active':''}" data-study="materials">Fichas y examen</button><button class="tab ${active==='legal'?'active':''}" data-study="legal">Escritos jurídicos</button><button class="tab ${active==='research'?'active':''}" data-study="research">Investigación web</button></div>`}
function bindStudyTabs(){document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>renderStudy(b.dataset.study))}
async function renderStudy(tab='home'){
  state.studyTab=tab;state.route='study';setHead('Estudio','HERRAMIENTAS ACADÉMICAS');
  if(tab==='home'){
    view.innerHTML=`<section class="hero blue"><div class="hero-content"><span class="eyebrow">ESTUDIO</span><h2>Elige el resultado que necesitas.</h2><p>Cada herramienta tiene su propio flujo para evitar formularios largos y opciones mezcladas.</p></div></section><div class="section-head"><div><h2>Herramientas</h2></div></div><section class="grid launch-grid">${launchCard('study','M','Monografía APA 7','Estructura, citas, índice, referencias y Word.','red','monograph')}${launchCard('study','F','Material de estudio','Ficha, explicación, simulacro, exposición o tarjetas.','blue','materials')}${launchCard('study','§','Escritos jurídicos','Borradores editables con datos y anexos.','yellow','legal')}${launchCard('study','⌕','Investigación web','Crossref, DOI, páginas web y auditoría de referencias.','green','research')}</section>`;bindLaunch();return;
  }
  if(tab==='monograph')return renderMonograph();
  if(tab==='materials')return renderStudyMaterials();
  if(tab==='legal')return renderLegal();
  if(tab==='research')return renderResearch();
}

async function extractInto(fileInput,targetSelector){
  const file=fileInput.files?.[0];if(!file)return;const fd=new FormData();fd.append('upload',file);toast('Leyendo documento…');
  const data=await api('/api/extract',{method:'POST',body:fd});document.querySelector(targetSelector).value=data.text||'';toast('Contenido importado');
}
function renderMonograph(){
  setHead('Monografía APA 7','ESTUDIO');
  const savedRefs=localStorage.getItem('dimitryApaRefs')||'';
  view.innerHTML=`${studyTabs('monograph')}<section class="grid two-col">
    <article class="panel"><div class="panel-head"><div><h2>Contenido de la monografía</h2><p>Pega el texto completo o importa un documento.</p></div></div>
      <div class="form-grid"><div class="field full"><label>TÍTULO</label><input id="monoTitle" placeholder="Título de la monografía"></div><div class="field"><label>AUTOR</label><input id="monoAuthor" placeholder="Pavel Franshesco Valverde Ccoscco"></div><div class="field"><label>CURSO</label><input id="monoCourse"></div><div class="field"><label>DOCENTE</label><input id="monoTeacher"></div><div class="field"><label>FECHA</label><input id="monoDate"></div><div class="field full"><label>IMPORTAR PDF, WORD O TXT</label><div class="file-picker"><input id="monoFile" class="file-input" type="file" accept=".pdf,.docx,.txt,.md"><label class="btn" for="monoFile">Seleccionar archivo</label><small id="monoFileName">Ningún archivo seleccionado</small></div></div><div class="field full"><label>CONTENIDO</label><textarea class="tall" id="monoContent" placeholder="Pega aquí todo el contenido, aunque todavía esté desordenado."></textarea></div><div class="field full"><label>BIBLIOGRAFÍA</label><textarea id="monoBibliography" placeholder="Una referencia por línea">${esc(savedRefs)}</textarea></div></div>
      <label class="check" style="margin-top:13px"><input id="monoWeb" type="checkbox"> Investigar en internet para verificar y proponer fuentes</label><div class="form-actions"><button class="btn primary" id="createMono">Crear Word APA 7</button><button class="btn" id="auditMono">Revisar citas y referencias</button><button class="btn green" data-study="research">Buscar fuentes</button></div><div id="monoResult"></div>
    </article>
    <aside class="panel"><div class="panel-head"><div><h3>Qué hará la herramienta</h3></div></div><div class="list"><div class="list-row"><div class="list-main"><span class="list-icon">1</span><div><h4>Ordenar</h4><small>Introducción, capítulos, conclusiones y recomendaciones.</small></div></div></div><div class="list-row"><div class="list-main"><span class="list-icon">2</span><div><h4>Formatear</h4><small>APA 7, títulos negros, negrita, márgenes e índice.</small></div></div></div><div class="list-row"><div class="list-main"><span class="list-icon">3</span><div><h4>Comprobar</h4><small>Citas faltantes, duplicados y referencias no usadas.</small></div></div></div></div><div class="notice info" style="margin-top:14px">La herramienta usa el proveedor configurado en Ajustes. Con investigación web activada puede revisar información reciente, pero las referencias deben comprobarse antes de entregar.</div></aside>
  </section>`;
  bindStudyTabs();document.querySelector('#monoFile').onchange=e=>{showSelectedFile(e.target);extractInto(e.target,'#monoContent').catch(err=>toast(err.message,'error'))};
  document.querySelector('#createMono').onclick=createMonograph;document.querySelector('#auditMono').onclick=auditMonograph;
}
async function createMonograph(){
  const content=val('#monoContent'),title=val('#monoTitle');if(!title||!content){toast('Completa el título y el contenido','error');return}
  const btn=document.querySelector('#createMono'),out=document.querySelector('#monoResult');btn.disabled=true;out.innerHTML='<div class="result">Creando documento…</div>';
  const payload={title,author:val('#monoAuthor'),institution:'Universidad Tecnológica de los Andes',course:val('#monoCourse'),teacher:val('#monoTeacher'),city:'Abancay, Perú',date:val('#monoDate'),content,bibliography:val('#monoBibliography'),use_ai:true,use_web:bool('#monoWeb')};
  try{const data=await api('/api/monographs/prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});localStorage.setItem('dimitryApaRefs',payload.bibliography);out.innerHTML=`<div class="result"><div class="notice good"><b>Documento creado correctamente.</b>${data.provider?`<br>Generado con ${esc(aiProviderLabel(data.provider))} · ${esc(data.model||'')}`:''}${data.warning?`<br>${esc(data.warning)}`:''}</div>${sourcePills(data.sources||[])}<div class="form-actions"><a class="btn blue" href="${data.download_url}">Descargar ${esc(data.filename)}</a></div><details><summary>Ver estructura generada</summary><pre>${esc(data.structured_text)}</pre></details></div>`;toast('Monografía creada')}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}finally{btn.disabled=false}
}
async function auditMonograph(){
  const out=document.querySelector('#monoResult');try{const data=await api('/api/research/audit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:val('#monoContent'),bibliography:val('#monoBibliography')})});out.innerHTML=`<div class="result"><h3>Revisión: ${data.score}/100</h3><div class="grid three-col"><div class="stat-card"><div><b>${data.citations}</b><small>CITAS DETECTADAS</small></div></div><div class="stat-card"><div><b>${data.references}</b><small>REFERENCIAS</small></div></div><div class="stat-card"><div><b>${data.dois.length}</b><small>DOI</small></div></div></div><p><b>Sin referencia:</b> ${esc(data.missing_references.join(', ')||'Ninguna detectada')}</p><p><b>Duplicadas:</b> ${esc(data.duplicates.join(' | ')||'Ninguna')}</p><p><b>Posiblemente no usadas:</b> ${esc(data.possibly_unused.slice(0,8).join(' | ')||'Ninguna')}</p></div>`}catch(error){toast(error.message,'error')}
}

async function renderStudyMaterials(){
  setHead('Fichas y preparación','ESTUDIO');let projects=[];try{projects=await api('/api/projects')}catch{}
  view.innerHTML=`${studyTabs('materials')}<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Generar material</h2><p>Pega el contenido o impórtalo desde un archivo.</p></div></div><div class="form-grid"><div class="field"><label>TIPO</label><select id="studyKind"><option value="ficha">Ficha completa</option><option value="simple">Explicación sencilla</option><option value="exam">Simulacro de examen</option><option value="speech">Guion de exposición</option><option value="cards">Tarjetas de memoria</option><option value="outline">Libro de estudio</option></select></div><div class="field"><label>PROYECTO OPCIONAL</label><select id="studyProject">${projectOptions(projects)}</select></div><div class="field full"><label>IMPORTAR PDF, WORD, POWERPOINT O TEXTO</label><div class="file-picker"><input id="studyFile" class="file-input" type="file" accept=".pdf,.docx,.pptx,.txt,.md"><label class="btn" for="studyFile">Seleccionar archivo</label><small id="studyFileName">Ningún archivo seleccionado</small></div></div><div class="field full"><label>CONTENIDO</label><textarea id="studyContent" class="tall"></textarea></div></div><label class="check" style="margin-top:13px"><input id="studyWeb" type="checkbox"> Completar con investigación en internet</label><div class="form-actions"><button class="btn blue" id="runStudy">Generar material</button></div><div id="studyResult"></div></article><aside class="panel"><h3>Sugerencias rápidas</h3><div class="chips"><button class="chip" data-prompt="Explícame cada concepto desde cero y agrega ejemplos.">Explicar desde cero</button><button class="chip" data-prompt="Crea preguntas difíciles y repreguntas del docente.">Preguntas difíciles</button><button class="chip" data-prompt="Organiza todo para una exposición de 3 minutos.">Exposición de 3 minutos</button></div><div class="notice info" style="margin-top:14px">El proyecto opcional añade sus reglas, notas y extractos de archivos como contexto.</div></aside></section>`;
  bindStudyTabs();document.querySelector('#studyFile').onchange=e=>{showSelectedFile(e.target);extractInto(e.target,'#studyContent').catch(err=>toast(err.message,'error'))};document.querySelector('#runStudy').onclick=runStudy;document.querySelectorAll('[data-prompt]').forEach((b,index)=>b.onclick=()=>{document.querySelector('#studyKind').value=['simple','exam','speech'][index];toast('Tipo de material seleccionado')})
}
async function runStudy(){const content=val('#studyContent');if(!content){toast('Pega o importa el contenido','error');return}const btn=document.querySelector('#runStudy'),out=document.querySelector('#studyResult');btn.disabled=true;out.innerHTML='<div class="result">Generando…</div>';try{const data=await api('/api/study/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:val('#studyKind'),content,project_id:Number(val('#studyProject'))||null,use_web:bool('#studyWeb')})});out.innerHTML=resultBox(data.response,`${sourcePills(data.sources||[])}<p><b>Motor:</b> ${esc(aiProviderLabel(data.provider))} · ${esc(data.model||'')}</p><div class="form-actions"><button class="btn small" id="copyStudy">Copiar</button></div>`);document.querySelector('#copyStudy').onclick=()=>navigator.clipboard.writeText(data.response).then(()=>toast('Copiado'))}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}finally{btn.disabled=false}}

function legacyRenderLegal(){
  setHead('Escritos jurídicos','ESTUDIO');view.innerHTML=`${studyTabs('legal')}<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Nuevo borrador jurídico</h2><p>La herramienta marca los datos que falten en lugar de inventarlos.</p></div></div><div class="form-grid"><div class="field"><label>TIPO DE ESCRITO</label><select id="legalKind"><option value="solicitud">Solicitud administrativa</option><option value="carta-notarial">Carta notarial</option><option value="apersonamiento">Apersonamiento</option><option value="reconsideracion">Recurso de reconsideración</option><option value="apelacion">Recurso de apelación</option><option value="denuncia">Denuncia</option><option value="descargo">Escrito de descargo</option><option value="carta-poder">Carta poder simple</option></select></div><div class="field"><label>AUTORIDAD O DESTINATARIO</label><input id="legalAuthority"></div><div class="field"><label>NOMBRE COMPLETO</label><input id="legalName"></div><div class="field"><label>DNI</label><input id="legalDni"></div><div class="field full"><label>PETITORIO</label><textarea id="legalRequest"></textarea></div><div class="field full"><label>HECHOS EN ORDEN CRONOLÓGICO</label><textarea id="legalFacts" class="tall"></textarea></div><div class="field full"><label>FUNDAMENTO LEGAL VERIFICADO</label><textarea id="legalBasis"></textarea></div><div class="field full"><label>PRUEBAS Y ANEXOS</label><textarea id="legalEvidence"></textarea></div></div><label class="check" style="margin-top:13px"><input id="legalWeb" type="checkbox"> Verificar en fuentes oficiales peruanas disponibles</label><div class="form-actions"><button class="btn yellow" id="createLegal">Crear Word editable</button></div><div id="legalResult"></div></article><aside class="panel"><div class="notice bad">Antes de presentar un escrito, revisa competencia, vía, plazo, firma, tasas, anexos y la vigencia de cada norma citada.</div><div class="section-head"><div><h3>Flujo recomendado</h3></div></div><div class="list"><div class="list-row"><div class="list-main"><span class="list-icon">1</span><div><h4>Completar hechos</h4><small>Fechas, personas y documentos.</small></div></div></div><div class="list-row"><div class="list-main"><span class="list-icon">2</span><div><h4>Verificar normas</h4><small>No uses artículos sin comprobarlos.</small></div></div></div><div class="list-row"><div class="list-main"><span class="list-icon">3</span><div><h4>Revisar el Word</h4><small>Corrige datos pendientes antes de firmar.</small></div></div></div></div></aside></section>`;bindStudyTabs();document.querySelector('#createLegal').onclick=createLegal
}
async function legacyCreateLegal(){const facts=val('#legalFacts'),request_text=val('#legalRequest');if(!facts||!request_text){toast('Completa el petitorio y los hechos','error');return}const out=document.querySelector('#legalResult');out.innerHTML='<div class="result">Redactando…</div>';try{const data=await api('/api/legal/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:val('#legalKind'),fields:{authority:val('#legalAuthority'),name:val('#legalName'),dni:val('#legalDni')},facts,legal_basis:val('#legalBasis'),evidence:val('#legalEvidence'),request_text,use_ai:true,verify_web:bool('#legalWeb')})});out.innerHTML=`<div class="result">${data.warning?notice(data.warning,'info'):''}${data.provider?`<p><b>Motor:</b> ${esc(aiProviderLabel(data.provider))} · ${esc(data.model||'')}</p>`:''}${sourcePills(data.sources||[])}<div class="form-actions"><a class="btn blue" href="${data.download_url}">Descargar ${esc(data.filename)}</a></div><pre>${esc(data.draft)}</pre></div>`;toast('Borrador creado')}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}}

function renderResearch(){
  setHead('Investigación web','ESTUDIO');view.innerHTML=`${studyTabs('research')}<section class="grid two-col"><article class="panel"><div class="tabs"><button class="tab active" data-research-tab="academic">Fuentes académicas</button><button class="tab" data-research-tab="web">Importar página</button><button class="tab" data-research-tab="audit">Auditar bibliografía</button></div><div id="researchWork"></div></article><aside class="panel"><div class="panel-head"><div><h3>Bibliografía temporal</h3><p>Las referencias añadidas aparecerán en Monografía APA 7.</p></div></div><div id="savedRefs" class="result"><pre>${esc(localStorage.getItem('dimitryApaRefs')||'Todavía no añadiste referencias.')}</pre></div><div class="form-actions"><button class="btn small danger" id="clearRefs">Vaciar lista</button></div><div class="notice info" style="margin-top:14px">Crossref proporciona metadatos académicos. Una referencia automática todavía debe compararse con el documento original.</div></aside></section>`;
  bindStudyTabs();document.querySelectorAll('[data-research-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-research-tab]').forEach(x=>x.classList.toggle('active',x===b));renderResearchTab(b.dataset.researchTab)});document.querySelector('#clearRefs').onclick=()=>{localStorage.removeItem('dimitryApaRefs');document.querySelector('#savedRefs').innerHTML='<pre>Lista vacía.</pre>';toast('Bibliografía temporal eliminada')};renderResearchTab('academic')
}
function renderResearchTab(tab){const box=document.querySelector('#researchWork');if(!box)return;
  if(tab==='academic'){box.innerHTML=`<div class="field"><label>TEMA, TÍTULO, AUTOR O DOI</label><input id="crossrefQuery" placeholder="Ej.: determinación judicial de la pena Perú"></div><div class="form-actions"><button class="btn green" id="searchCrossref">Buscar en Crossref</button></div><div id="crossrefResults" style="margin-top:15px"></div>`;document.querySelector('#searchCrossref').onclick=searchCrossref}
  if(tab==='web'){box.innerHTML=`<div class="field"><label>URL DE LA FUENTE</label><input id="webUrl" placeholder="https://..."></div><div class="field" style="margin-top:12px"><label>TÍTULO OPCIONAL</label><input id="webTitle"></div><div class="form-actions"><button class="btn blue" id="importWeb">Descargar e indexar</button></div><div id="webResult"></div>`;document.querySelector('#importWeb').onclick=importWeb}
  if(tab==='audit'){box.innerHTML=`<div class="field"><label>CONTENIDO CON CITAS</label><textarea class="tall" id="auditContent"></textarea></div><div class="field" style="margin-top:12px"><label>REFERENCIAS</label><textarea id="auditRefs">${esc(localStorage.getItem('dimitryApaRefs')||'')}</textarea></div><div class="form-actions"><button class="btn primary" id="runAudit">Revisar</button></div><div id="auditResult"></div>`;document.querySelector('#runAudit').onclick=runResearchAudit}
}
async function searchCrossref(){const query=val('#crossrefQuery');if(!query){toast('Escribe un tema o DOI','error');return}const out=document.querySelector('#crossrefResults');out.innerHTML='<div class="loading"><div class="spinner"></div>Buscando metadatos…</div>';try{const data=await api('/api/research/crossref/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,rows:10})});out.innerHTML=data.results.length?data.results.map((item,i)=>`<div class="research-result"><h4>${esc(item.title)}</h4><p>${esc(item.authors)} · ${esc(item.year)}${item.doi?` · DOI ${esc(item.doi)}`:''}</p><div class="apa">${esc(item.apa_reference)}</div><div class="form-actions"><button class="btn small green" data-add-ref="${i}">Añadir referencia</button><button class="btn small" data-save-ref="${i}">Guardar en biblioteca</button></div></div>`).join(''):'<div class="empty"><b>Sin resultados</b>Prueba con otras palabras.</div>';out.querySelectorAll('[data-add-ref]').forEach(b=>b.onclick=()=>addReference(data.results[Number(b.dataset.addRef)]));out.querySelectorAll('[data-save-ref]').forEach(b=>b.onclick=()=>saveReference(data.results[Number(b.dataset.saveRef)]))}catch(error){out.innerHTML=notice(error.message,'bad')}}
function addReference(item){const current=localStorage.getItem('dimitryApaRefs')||'';const lines=current.split('\n').map(x=>x.trim()).filter(Boolean);if(!lines.includes(item.apa_reference))lines.push(item.apa_reference);localStorage.setItem('dimitryApaRefs',lines.join('\n'));const saved=document.querySelector('#savedRefs');if(saved)saved.innerHTML=`<pre>${esc(lines.join('\n'))}</pre>`;toast('Referencia añadida')}
async function saveReference(item){try{await api('/api/research/items',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item})});addReference(item);toast('Fuente guardada en la biblioteca')}catch(error){toast(error.message,'error')}}
async function importWeb(){const out=document.querySelector('#webResult');try{const data=await api('/api/research/web-import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:val('#webUrl'),title:val('#webTitle'),domain:'research'})});out.innerHTML=`<div class="result">${notice(`Fuente importada: ${data.title}`,'good')}<p><b>Calidad orientativa:</b> ${esc(data.quality.level)} · ${data.characters} caracteres indexados.</p></div>`;toast('Página importada')}catch(error){out.innerHTML=notice(error.message,'bad')}}
async function runResearchAudit(){const out=document.querySelector('#auditResult');try{const data=await api('/api/research/audit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:val('#auditContent'),bibliography:val('#auditRefs')})});out.innerHTML=`<div class="result"><h3>Puntaje orientativo: ${data.score}/100</h3><p><b>Citas sin referencia:</b> ${esc(data.missing_references.join(', ')||'Ninguna')}</p><p><b>Duplicadas:</b> ${esc(data.duplicates.join(' | ')||'Ninguna')}</p><p><b>Referencias posiblemente no usadas:</b> ${esc(data.possibly_unused.join(' | ')||'Ninguna')}</p></div>`}catch(error){out.innerHTML=notice(error.message,'bad')}}

function palEditorFeature(icon,title,text){return `<div class="stat-card"><span class="stat-icon">${icon}</span><div><b>${esc(title)}</b><small>${esc(text)}</small></div></div>`}
function palSessionCard(session,editorReady){const files=(session.files||[]).map(file=>`<span class="source-pill">${esc(file.kind_label||file.name)}</span>`).join('');return `<div class="list-row" style="align-items:flex-start"><div class="list-main"><span class="list-icon">S</span><div><h4>${esc(session.name)}</h4><small>${esc(session.kind_label)} · ${fmtBytes(session.size)} · ${fmtDate(session.created_at)}</small><div class="chat-sources" style="margin-top:8px">${files}</div><small style="display:block;margin-top:7px">Respaldo automático: ${session.backup_created?'listo y protegido':'no disponible'}</small></div></div><div class="form-actions" style="margin:0;justify-content:flex-end"><button class="btn small primary" data-pal-perfect="${esc(session.id)}">Preparar parejas perfectas</button><button class="btn small green" data-pal-launch="${esc(session.id)}" ${editorReady?'':'disabled'} title="${editorReady?'Abrir la copia en el editor':'Primero instala el editor completo'}">${editorReady?'Abrir editor':'Editor pendiente'}</button><button class="btn small" data-pal-folder="${esc(session.id)}">Abrir carpeta</button><a class="btn small" href="/api/palworld/workspace/sessions/${encodeURIComponent(session.id)}/download?variant=working">Descargar copia de trabajo</a><a class="btn small" href="/api/palworld/workspace/sessions/${encodeURIComponent(session.id)}/download?variant=backup">Descargar respaldo</a><button class="btn small" data-pal-restore="${esc(session.id)}">Restaurar desde respaldo</button><button class="btn small danger" data-pal-delete="${esc(session.id)}">Eliminar sesión</button></div></div>`}
async function uploadPalSave(input,expectedKind){const file=input.files?.[0];if(!file)return;const data=new FormData();data.append('upload',file);data.append('expected_kind',expectedKind);openModal('Importando guardado',`<div class="loading"><div class="spinner"></div>Creando una copia de seguridad y preparando ${esc(file.name)}…</div>`);try{const result=await api('/api/palworld/workspace/upload',{method:'POST',body:data});closeModal();toast(`Guardado preparado: ${result.name}`,'ok');await renderPalworld('editor')}catch(error){closeModal();toast(error.message,'error')}finally{input.value=''}}
async function installPalEditor(button){if(button){button.disabled=true;button.textContent='Descargando editor…'}openModal('Preparando editor completo','<div class="loading"><div class="spinner"></div>Descargando y verificando Palworld Save Pal. La primera vez puede tardar varios minutos.</div>');try{const result=await api('/api/palworld/editor/install',{method:'POST'});closeModal();toast(`Editor ${result.installed_version||''} preparado`,'ok');await renderPalworld('editor')}catch(error){closeModal();toast(error.message,'error');if(button){button.disabled=false;button.textContent='Instalar editor completo'}}}
async function launchPalEditor(sessionId='',button=null){
  if(button)button.disabled=true;
  try{
    const result=await api('/api/palworld/editor/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:sessionId})});
    const opened=result.editor_url?window.open(result.editor_url,'dimitry-palworld-save-pal','noopener'):null;
    if(result.editor_url&&!opened){openModal('Editor Palworld',`<p>${esc(result.message||'El editor está preparado.')}</p><div class="form-actions"><a class="btn green" href="${esc(result.editor_url)}" target="_blank" rel="noopener">Abrir editor ahora</a></div>`)}
    toast(result.message||'Editor abierto','ok');
  }catch(error){toast(error.message,'error')}
  finally{if(button)button.disabled=false}
}
async function preparePerfectPals(sessionId,button){
  openModal('Parejas perfectas de Pals',`<p>Dimitry Hub actualizará el catálogo del editor y preparará perfiles masivos. No escribirá directamente sobre tu save: la copia automática de esta sesión se conserva intacta.</p><div class="notice info">Cada especie tendrá un macho y una hembra de nivel 1, cuatro pasivas elegidas por función, IV y almas máximos, rango máximo y trabajo nativo sin modificar.</div><div class="form-actions"><button class="btn primary" id="confirmPerfectPals">Actualizar y generar</button><button class="btn" id="cancelPerfectPals">Cancelar</button></div>`);
  document.querySelector('#cancelPerfectPals').onclick=closeModal;
  document.querySelector('#confirmPerfectPals').onclick=async()=>{
    const confirm=document.querySelector('#confirmPerfectPals');confirm.disabled=true;confirm.textContent='Analizando catálogo…';
    try{
      const data=await api('/api/palworld/perfect-pals/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_catalog:true})});
      const newer=data.new_species_ids||[];const roles=Object.entries(data.roles||{}).map(([role,count])=>`${esc(role)}: ${count}`).join(' · ');
      openModal('Perfiles perfectos preparados',`<div class="result"><h3>${data.pairs} parejas · ${data.profiles} perfiles</h3><p>${roles}</p><div class="notice good">Validado: nivel 1, macho y hembra, cuatro pasivas, IV 100, almas 20, rango 5 y trabajo nativo.</div>${newer.length?`<div class="notice info"><b>Especies nuevas detectadas (${newer.length}):</b> ${newer.map(esc).join(', ')}</div>`:'<div class="notice info">Esta generación creó la referencia inicial. En una futura actualización se identificarán únicamente las especies nuevas.</div>'}<div class="form-actions"><a class="btn primary" href="${esc(data.downloads.male)}">Perfiles machos</a><a class="btn primary" href="${esc(data.downloads.female)}">Perfiles hembras</a><a class="btn" href="${esc(data.downloads.new)}">Solo especies nuevas</a><a class="btn" href="${esc(data.downloads.plan)}">Plan completo</a></div><h4 style="margin-top:16px">Aplicación masiva segura</h4><ol><li>Abre el editor con el botón inferior y carga la copia de esta sesión.</li><li>En <b>Presets</b>, importa los ZIP de machos y hembras.</li><li>En la Caja Pal usa <b>Llenar Pals</b>: selecciona solo normales y todos los perfiles macho; guarda. Repite una vez con todos los perfiles hembra.</li><li>Si usas <b>GlobalPalStorage.sav</b>, repite las mismas dos operaciones en Caja Pal Global para conservar las dos parejas también allí.</li><li>Para un save antiguo, usa “Solo especies nuevas”, agrega únicamente esas parejas y aplica sus perfiles juntos; así no duplicas especies anteriores.</li><li>Guarda desde el editor y verifica el resultado dentro del juego antes de reemplazar tu save.</li></ol><div class="form-actions"><button class="btn green" id="launchPerfectEditor">Abrir editor con esta sesión</button><button class="btn" id="closePerfectResult">Cerrar</button></div></div>`);
      document.querySelector('#launchPerfectEditor').onclick=()=>launchPalEditor(sessionId,document.querySelector('#launchPerfectEditor'));
      document.querySelector('#closePerfectResult').onclick=closeModal;
      toast('Perfiles macho y hembra generados y validados','ok');
    }catch(error){toast(error.message,'error');confirm.disabled=false;confirm.textContent='Actualizar y generar'}
  };
  if(button)button.disabled=false;
}
async function openPalFolder(sessionId){try{await api(`/api/palworld/workspace/sessions/${encodeURIComponent(sessionId)}/open-folder`,{method:'POST'});toast('Carpeta de trabajo abierta','ok')}catch(error){toast(error.message,'error')}}
async function deletePalSession(sessionId){openModal('Eliminar sesión',`<p>Se eliminará la copia de trabajo de Dimitry Hub. Tu archivo original del juego no será tocado.</p><div class="form-actions"><button class="btn danger" id="confirmDeletePal">Eliminar sesión</button><button class="btn" id="cancelDeletePal">Cancelar</button></div>`);document.querySelector('#cancelDeletePal').onclick=closeModal;document.querySelector('#confirmDeletePal').onclick=async()=>{try{await api(`/api/palworld/workspace/sessions/${encodeURIComponent(sessionId)}`,{method:'DELETE'});closeModal();toast('Sesión eliminada');await renderPalworld()}catch(error){toast(error.message,'error')}}}
