async function renderPalworld(mode='all'){
  const pageTitle=mode==='wiki'?'Palworld Wiki':mode==='editor'?'Editor Palworld':'Palworld';
  setHead(pageTitle,mode==='wiki'?'BIBLIOTECA Y GUÍAS':mode==='editor'?'EDICIÓN SEGURA DE PARTIDAS':'CENTRO ESPECIALIZADO');loading('Abriendo el centro Palworld');
  try{const [summary,sync,workspace]=await Promise.all([api('/api/knowledge/palworld/summary'),api('/api/sync/status'),api('/api/palworld/workspace/status')]);const editorSource=sync.sources.find(s=>s.source_key==='palworld-editor-github')||{};const news=sync.sources.find(s=>s.source_key==='palworld-steam-news')||{};const editor=workspace.editor||{};const sessions=workspace.sessions||[];
    view.innerHTML=`<section class="hero green"><div class="hero-content"><span class="eyebrow">PALWORLD CENTER</span><h2>Biblioteca, consultas y edición segura de saves.</h2><p>Sube Level.sav, GlobalPalStorage.sav o un ZIP completo. Dimitry Hub crea una copia automática y abre el editor completo sin tocar el archivo original.</p><div class="hero-actions"><button class="btn white" id="chooseLevel">Subir Level.sav</button><button class="btn ghost" id="chooseGlobal">Subir GlobalPalStorage.sav</button><button class="btn ghost" id="chooseSaveZip">Subir ZIP del guardado</button><button class="btn ghost" id="palSync">Sincronizar datos</button></div><input type="file" id="levelUpload" accept=".sav" hidden><input type="file" id="globalUpload" accept=".sav" hidden><input type="file" id="saveZipUpload" accept=".zip" hidden></div></section>
    <div class="section-head"><div><h2>Editor de saves</h2><p>Componente completo basado en Palworld Save Pal. Se guarda dentro de Dimitry Hub y se actualiza desde su publicación oficial.</p></div><span class="power-badge ${editor.installed?'':'off'}"><i></i>${editor.installed?`Editor ${esc(editor.installed_version||'preparado')}`:'Editor no instalado'}</span></div>
    <section class="grid two-col"><article class="panel"><div class="panel-head"><div><h3>Archivos admitidos</h3><p>Cada importación genera una sesión independiente con copia de seguridad.</p></div></div><section class="grid stats-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${palEditorFeature('L','Level.sav','Pals, jugadores, inventarios, guilds y mundo')}${palEditorFeature('G','GlobalPalStorage.sav','Caja Pal global y almacenamiento')}${palEditorFeature('Z','ZIP completo','Save de Steam, servidor o Game Pass')}${palEditorFeature('P','Player .sav','Personaje y estadísticas')}</section><div class="form-actions"><button class="btn green" id="installPalEditor">${editor.installed?'Actualizar componente':'Instalar editor completo'}</button><button class="btn" id="openPalEditor" ${editor.installed?'':'disabled'}>Abrir editor sin archivo</button></div><div class="notice info">El editor completo permite Palbox, Caja Pal global, sexo, nivel, pasivas, habilidades, IV, almas, rango, trabajo, jugadores, inventario, tecnologías, mapa, misiones, guilds y edición cruda. Trabaja siempre sobre la copia de la sesión.</div></article><aside class="panel"><h3>Automatización masiva de Dimitry</h3><div class="list"><div class="list-row"><div><h4>Perfiles por especie y función</h4><small>Dimitry analiza el catálogo actualizado y elige exactamente cuatro pasivas para combate, montura, trabajo o rancho.</small></div></div><div class="list-row"><div><h4>Pareja macho y hembra</h4><small>Genera dos paquetes importables para llenar la Caja Pal completa en dos operaciones masivas.</small></div></div><div class="list-row"><div><h4>Reglas protegidas</h4><small>Nivel 1, IV y almas máximos, rango máximo, trabajo nativo, Gumoss con flor roja, Panthalus alfa y exclusiones históricas.</small></div></div><div class="list-row"><div><h4>Actualizaciones futuras</h4><small>Compara el catálogo anterior con el nuevo y prepara un paquete separado únicamente para especies recién añadidas.</small></div></div></div><p style="margin-top:12px;color:var(--muted)">Usa “Preparar parejas perfectas” en una sesión. Dimitry crea los perfiles y el editor oficial realiza la escritura compatible sobre la copia.</p></aside></section>
    <div class="section-head"><div><h2>Sesiones preparadas</h2><p>${sessions.length?`${sessions.length} sesión(es) disponibles`:'Todavía no subiste un save.'}</p></div></div><section class="panel"><div class="list">${sessions.map(session=>palSessionCard(session,editor.installed)).join('')||'<div class="empty"><b>Sin sesiones</b>Sube Level.sav, GlobalPalStorage.sav o un ZIP completo.</div>'}</div></section>
    <div class="section-head"><div><h2>Consulta de la biblioteca</h2><p>Funciona con respuesta local aunque no tengas OpenAI ni Ollama configurados.</p></div></div><section class="grid two-col"><article class="panel"><div class="field"><label>PREGUNTA</label><textarea class="tall" id="palQuestion" placeholder="Ej.: ¿Qué pasivas o códigos internos aparecen para este Pal?"></textarea></div><div class="chips" style="margin-top:12px"><button class="chip" data-pal="¿Cuáles son las reglas permanentes de nuestro proyecto Palworld?">Reglas del proyecto</button><button class="chip" data-pal="Busca códigos internos relacionados con Pals y variantes nuevas.">Códigos internos</button><button class="chip" data-pal="Resume las noticias recientes sobre nuevos Pals, objetos o cambios de partidas guardadas.">Novedades relevantes</button></div><div class="form-actions"><button class="btn green" id="askPal">Consultar biblioteca</button></div><div id="palAnswer"></div></article><aside class="panel"><div class="panel-head"><div><h3>Estado de datos</h3><p>Los datos guardados siguen disponibles aunque una fuente no responda.</p></div></div><section class="grid stats-grid" style="grid-template-columns:1fr 1fr">${palEditorFeature('P',summary.entries,'Entradas indexadas')}${palEditorFeature('↻',sourceStatusLabel(editorSource.status),'Estado del editor')}${palEditorFeature('N',sourceStatusLabel(news.status),'Noticias oficiales')}${palEditorFeature('V',(editorSource.current_version||'—').slice(0,12),'Versión técnica')}</section><div class="list" style="margin-top:14px">${summary.bundles.slice(0,6).map(b=>`<div class="list-row"><div><h4>${esc(b.name)}</h4><small>${b.entry_count} entradas · ${fmtDate(b.updated_at)}</small></div></div>`).join('')||'<div class="empty"><b>Sin paquetes importados</b>La consulta todavía puede usar las fuentes sincronizadas.</div>'}</div></aside></section>`;
    bindLaunch();
    const heroActions=view.querySelector('.hero-actions');if(heroActions&&!document.querySelector('#choosePlayer')){heroActions.insertAdjacentHTML('beforeend','<button class="btn ghost" id="choosePlayer">Subir Player .sav</button><input type="file" id="playerUpload" accept=".sav" hidden>')}
    document.querySelector('#chooseLevel').onclick=()=>document.querySelector('#levelUpload').click();document.querySelector('#chooseGlobal').onclick=()=>document.querySelector('#globalUpload').click();document.querySelector('#chooseSaveZip').onclick=()=>document.querySelector('#saveZipUpload').click();document.querySelector('#choosePlayer').onclick=()=>document.querySelector('#playerUpload').click();document.querySelector('#levelUpload').onchange=e=>uploadPalSave(e.target,'level');document.querySelector('#globalUpload').onchange=e=>uploadPalSave(e.target,'global_storage');document.querySelector('#saveZipUpload').onchange=e=>uploadPalSave(e.target,'save_bundle');document.querySelector('#playerUpload').onchange=e=>uploadPalSave(e.target,'player');document.querySelector('#installPalEditor').onclick=e=>installPalEditor(e.currentTarget);document.querySelector('#openPalEditor').onclick=e=>launchPalEditor('',e.currentTarget);document.querySelector('#palSync').onclick=runSync;document.querySelector('#askPal').onclick=()=>askKnowledge('palworld','#palQuestion','#palAnswer');document.querySelectorAll('[data-pal]').forEach(b=>b.onclick=()=>document.querySelector('#palQuestion').value=b.dataset.pal);document.querySelectorAll('[data-pal-perfect]').forEach(b=>b.onclick=()=>preparePerfectPals(b.dataset.palPerfect,b));document.querySelectorAll('[data-pal-launch]').forEach(b=>b.onclick=()=>launchPalEditor(b.dataset.palLaunch,b));document.querySelectorAll('[data-pal-folder]').forEach(b=>b.onclick=()=>openPalFolder(b.dataset.palFolder));document.querySelectorAll('[data-pal-restore]').forEach(b=>b.onclick=()=>restorePalSession(b.dataset.palRestore));document.querySelectorAll('[data-pal-delete]').forEach(b=>b.onclick=()=>deletePalSession(b.dataset.palDelete))
    const hero=view.querySelector('.hero');
    if(mode==='wiki'){
      hero.querySelector('.eyebrow').textContent='PALWORLD WIKI';hero.querySelector('h2').textContent='Consulta guías y datos de Palworld.';hero.querySelector('p').textContent='Busca reglas del proyecto, códigos internos, noticias y conocimiento sincronizado, incluso sin un proveedor de IA configurado.';
      ['#chooseLevel','#chooseGlobal','#chooseSaveZip','#choosePlayer'].forEach(selector=>{const element=document.querySelector(selector);if(element)element.remove()});
    }
    if(mode==='editor'){
      hero.querySelector('.eyebrow').textContent='EDITOR PALWORLD';hero.querySelector('h2').textContent='Edita una copia segura de tu partida.';hero.querySelector('p').textContent='Importa Level.sav, GlobalPalStorage.sav, Player .sav o un ZIP completo. Dimitry Hub conserva un respaldo y nunca modifica directamente el archivo original.';
      const syncButton=document.querySelector('#palSync');if(syncButton)syncButton.remove();
    }
    if(mode!=='all'){
      const headings=[...view.querySelectorAll('.section-head')];
      headings.forEach(heading=>{
        const text=heading.textContent||'';
        const isWiki=text.includes('Consulta de la biblioteca');
        const isEditor=text.includes('Editor de saves')||text.includes('Sesiones preparadas');
        if((mode==='wiki'&&isEditor)||(mode==='editor'&&isWiki)){
          const content=heading.nextElementSibling;heading.remove();if(content)content.remove();
        }
      });
    }
  }catch(error){throw error}
}
async function renderGameMod(){
  setHead('Game Modification','LABORATORIO TÉCNICO');loading('Abriendo el laboratorio');
  try{
    const summary=await api('/api/knowledge/gamemod/summary');
    view.innerHTML=`<section class="hero dark"><div class="hero-content"><span class="eyebrow">GAME LAB</span><h2>Analiza y crea Lua con controles claros.</h2><p>Revisa scripts sin ejecutarlos, crea menús legibles para GameGuardian y estudia tus propios dumps o paquetes de código.</p><div class="hero-actions"><button class="btn white" id="gmUpload">Subir ZIP técnico</button></div></div></section>
    <div class="section-head"><div><h2>Herramientas Lua</h2><p>El analizador nunca ejecuta el archivo seleccionado.</p></div></div>
    <section class="grid two-col">
      <article class="panel"><h3>Revisar un archivo Lua</h3><p>Detecta el entorno, funciones, llamadas de GameGuardian, ofuscación e indicadores sensibles.</p><div class="field"><label>ARCHIVO .LUA</label><div class="file-picker"><input id="luaFile" class="file-input" type="file" accept=".lua,text/x-lua"><label class="btn" for="luaFile">Seleccionar archivo</label><small id="luaFileName">Ningún archivo seleccionado</small></div></div><div class="form-actions"><button class="btn blue" id="analyzeLua">Analizar sin ejecutar</button></div><div id="luaAnalysis"></div></article>
      <article class="panel"><h3>Crear script para GameGuardian</h3><div class="form-grid"><div class="field"><label>NOMBRE</label><input id="luaName" maxlength="120" placeholder="Mi herramienta"></div><div class="field"><label>AUTOR</label><input id="luaAuthor" maxlength="120" placeholder="Nombre o alias"></div><div class="field full"><label>FINALIDAD</label><textarea id="luaDescription" placeholder="Describe para qué sirve y en qué versión fue comprobado."></textarea></div><div class="field full"><label>ACCIONES</label><textarea id="luaChanges" class="tall" placeholder="Una por línea: Nombre | búsqueda | tipo | valor nuevo\nEjemplo: Prueba local | 100 | DWORD | 999"></textarea><small>Tipos admitidos: BYTE, WORD, DWORD, QWORD, FLOAT, DOUBLE y XOR. Debes aportar valores reales comprobados; Dimitry Hub no inventa direcciones ni patrones.</small></div></div><div class="form-actions"><button class="btn primary" id="generateLua">Crear y descargar Lua</button></div><div id="luaGenerated"></div></article>
    </section>
    <div class="section-head"><div><h2>Consulta técnica</h2><p>${summary.entries} entradas indexadas.</p></div></div>
    <section class="grid two-col"><article class="panel"><div class="field"><label>PREGUNTA</label><textarea id="gmQuestion" class="tall" placeholder="Ej.: identifica clases relacionadas con inventario y explica cuáles parecen guardar datos."></textarea></div><div class="chips" style="margin-top:12px"><button class="chip" data-gm="Identifica si el material corresponde a Unity Mono o IL2CPP y explica las evidencias.">Detectar Unity</button><button class="chip" data-gm="Busca clases, campos y métodos relacionados con inventario, guardado y desbloqueos.">Buscar símbolos</button><button class="chip" data-gm="Explica qué cambios parecen temporales y cuáles podrían persistir al reiniciar.">Persistencia</button></div><div class="form-actions"><button class="btn blue" id="askGm">Analizar biblioteca</button></div><div id="gmAnswer"></div></article><aside class="panel"><h3>Biblioteca</h3><div class="stats-grid grid" style="grid-template-columns:1fr 1fr"><div class="stat-card"><div><b>${summary.entries}</b><small>ENTRADAS</small></div></div><div class="stat-card"><div><b>${summary.bundles.length}</b><small>PAQUETES</small></div></div></div><div class="notice bad" style="margin-top:14px">Trabaja sobre copias propias. No uses estas herramientas para evadir pagos, DRM, anticheat ni afectar servicios, partidas o cuentas ajenas.</div></aside></section>`;
    document.querySelector('#gmUpload').onclick=()=>knowledgeUpload('gamemod','Importar dump o código');
    document.querySelector('#askGm').onclick=()=>askKnowledge('gamemod','#gmQuestion','#gmAnswer');
    document.querySelectorAll('[data-gm]').forEach(b=>b.onclick=()=>document.querySelector('#gmQuestion').value=b.dataset.gm);
    document.querySelector('#luaFile').onchange=e=>showSelectedFile(e.target);
    document.querySelector('#analyzeLua').onclick=async()=>{
      const file=document.querySelector('#luaFile').files[0],out=document.querySelector('#luaAnalysis');
      if(!file){toast('Selecciona un archivo .lua','error');return}
      const form=new FormData();form.append('upload',file);out.innerHTML='<div class="loading"><div class="spinner"></div>Revisando el texto sin ejecutarlo…</div>';
      try{const data=await api('/api/gamemod/lua/analyze',{method:'POST',body:form});const calls=Object.entries(data.api_calls||{}).map(([key,count])=>`${key}: ${count}`).join(' · ')||'Ninguna';const findings=(data.findings||[]).map(item=>`<div class="notice ${item.level==='danger'?'bad':'info'}"><b>${esc(item.label)}</b><br>${esc(item.detail)}</div>`).join('');out.innerHTML=`<div class="result"><p><b>Entorno:</b> ${esc(data.environment)} · <b>Riesgo orientativo:</b> ${esc(data.risk_level)} · <b>Líneas:</b> ${data.line_count}</p><p><b>Funciones:</b> ${esc((data.functions||[]).join(', ')||'No detectadas')}</p><p><b>Llamadas:</b> ${esc(calls)}</p>${findings}<details><summary>Vista previa decodificada</summary><pre>${esc(data.preview)}</pre></details></div>`;toast('Análisis terminado')}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}
    };
    document.querySelector('#generateLua').onclick=async()=>{
      const out=document.querySelector('#luaGenerated'),payload={name:val('#luaName'),author:val('#luaAuthor'),description:val('#luaDescription'),changes:val('#luaChanges')};
      if(!payload.name||!payload.changes){toast('Completa el nombre y las acciones','error');return}
      out.innerHTML='<div class="loading"><div class="spinner"></div>Creando un script legible…</div>';
      try{const data=await api('/api/gamemod/lua/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});out.innerHTML=`<div class="result"><p><b>${data.actions}</b> acción(es) incorporadas. El menú incluye restauración de los valores guardados durante la sesión.</p><div class="form-actions"><a class="btn blue" href="${data.download_url}">Descargar ${esc(data.filename)}</a></div><details><summary>Ver código generado</summary><pre>${esc(data.preview)}</pre></details></div>`;toast('Script Lua creado')}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}
    };
  }catch(error){view.innerHTML=notice(error.message,'bad')}
}
async function askKnowledge(domain,inputSelector,outSelector){const question=val(inputSelector);if(!question){toast('Escribe una pregunta','error');return}const out=document.querySelector(outSelector);const button=document.querySelector('#askPal');if(button)button.disabled=true;out.innerHTML='<div class="loading"><div class="spinner"></div>Buscando en la biblioteca local…</div>';try{const data=await api('/api/knowledge/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain,question})});const sources=data.results?.map(r=>r.title).slice(0,8).join(' · ')||'Sin coincidencias';const mode=data.offline?'Respuesta local':'Respuesta con IA';out.innerHTML=resultBox(data.answer,`${data.warning?notice(data.warning,'info'):''}<p><b>Modo:</b> ${esc(mode)}</p><p><b>Fuentes:</b> ${esc(sources)}</p>`)}catch(error){out.innerHTML=notice(error.message,'bad')}finally{if(button)button.disabled=false}}
let syncBusy=false;
async function runSync(){if(syncBusy){toast('La sincronización ya está en curso','info');return}syncBusy=true;const buttons=[...document.querySelectorAll('#syncAll,#palSync,#quickSync')];buttons.forEach(b=>{b.disabled=true});const statusText=document.querySelector('#connectionText');if(statusText)statusText.textContent='Sincronizando…';try{const data=await api('/api/sync/all',{method:'POST'});if(data.status==='running'){toast('La sincronización ya estaba en curso','info');return}const errors=data.results?.filter(x=>x.error)||[];if(errors.length){const details=errors.map(item=>`<div class="notice info"><b>${esc(typeof syncSourceName==='function'?syncSourceName(item.source):item.source)}</b><br>${esc(friendlyConnectionError(item.error))}</div>`).join('');toast(`Sincronización parcial: ${errors.length} fuente(s) sin conexión`,'error');openModal('Algunas fuentes no respondieron',`<p>La aplicación seguirá usando la última información válida guardada.</p>${details}`)}else{toast(`Sincronización completada · ${data.changed_count} fuente(s) cambiaron`,'ok')}if(state.route==='updates')await renderUpdates();else if(state.route==='palworld')await renderPalworld()}catch(error){toast(friendlyConnectionError(error.message),'error')}finally{syncBusy=false;buttons.forEach(b=>{b.disabled=false});if(statusText)statusText.textContent='Preparado'}}
async function renderProjects(){setHead('Proyectos','CONTEXTO, NOTAS Y ARCHIVOS');loading('Cargando proyectos');try{state.projects=await api('/api/projects');view.innerHTML=`<div class="toolbar"><div class="search"><input id="projectSearch" placeholder="Buscar proyecto"><span>⌕</span></div><button class="btn primary" id="newProject">Nuevo proyecto</button></div><section id="projectGrid" class="grid project-grid">${projectCards(state.projects)}</section>`;document.querySelector('#newProject').onclick=()=>projectForm();document.querySelector('#projectSearch').oninput=e=>document.querySelector('#projectGrid').innerHTML=projectCards(state.projects.filter(p=>`${p.name} ${p.category} ${p.description}`.toLowerCase().includes(e.target.value.toLowerCase())));bindProjectCards()}catch(error){view.innerHTML=notice(error.message,'bad')}}
function projectCards(items){return items.map(p=>`<article class="project-card" data-project="${p.id}"><div class="project-banner ${esc(p.accent)}"><b>${esc(p.category)}</b></div><div class="project-body"><h3>${esc(p.name)}</h3><p>${esc(p.description||'Sin descripción')}</p><div class="project-meta"><span>${p.note_count} notas</span><span>${p.file_count} archivos</span></div></div></article>`).join('')||'<div class="empty"><b>Sin proyectos</b>Crea el primero.</div>'}
function bindProjectCards(){document.querySelectorAll('[data-project]').forEach(c=>c.onclick=()=>renderProject(Number(c.dataset.project)))}
function projectForm(project=null){openModal(project?'Editar proyecto':'Nuevo proyecto',`<form id="projectForm"><div class="form-grid"><div class="field"><label>NOMBRE</label><input name="name" required value="${esc(project?.name||'')}"></div><div class="field"><label>CATEGORÍA</label><select name="category"><option>Estudio</option><option>Gaming</option><option>Personal</option><option>General</option></select></div><div class="field full"><label>DESCRIPCIÓN</label><textarea name="description">${esc(project?.description||'')}</textarea></div><div class="field full"><label>REGLAS PERMANENTES</label><textarea name="permanent_instructions">${esc(project?.permanent_instructions||'')}</textarea></div><div class="field"><label>COLOR</label><select name="accent"><option value="blue">Azul</option><option value="red">Rojo</option><option value="green">Verde</option><option value="yellow">Amarillo</option></select></div></div><div class="form-actions"><button class="btn primary">Guardar</button></div></form>`);const form=document.querySelector('#projectForm');form.category.value=project?.category||'General';form.accent.value=project?.accent||'blue';form.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));try{await api(project?`/api/projects/${project.id}`:'/api/projects',{method:project?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeModal();toast('Proyecto guardado');renderProjects()}catch(error){toast(error.message,'error')}}}
async function renderProject(id){state.route='projects';setHead('Proyecto','CONTEXTO Y ARCHIVOS');loading('Abriendo proyecto');try{const data=await api(`/api/projects/${id}`);state.currentProject=data;view.innerHTML=`<div class="toolbar"><button class="btn" data-go="projects">← Volver</button><div class="form-actions"><a class="btn" href="/api/projects/${id}/context">Descargar CONTEXT.md</a><a class="btn blue" href="/api/projects/${id}/export">Exportar ZIP</a></div></div><section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>${esc(data.project.name)}</h2><p>${esc(data.project.description)}</p></div><button class="btn small" id="editProject">Editar</button></div><div class="notice info">${esc(data.project.permanent_instructions||'Sin reglas permanentes.')}</div><div class="section-head"><div><h3>Notas</h3></div><button class="btn small primary" id="newNote">Añadir nota</button></div><div class="list">${data.notes.map(n=>`<div class="list-row"><div><h4>${esc(n.title)}</h4><p style="white-space:pre-wrap">${esc(n.body)}</p></div></div>`).join('')||'<div class="empty"><b>Sin notas</b>Guarda decisiones y reglas importantes.</div>'}</div></article><aside class="panel"><div class="panel-head"><div><h3>Archivos</h3><p>${data.files.length} guardados</p></div></div><form id="projectFile"><div class="field"><input name="upload" type="file" required></div><div class="form-actions"><button class="btn primary small">Importar</button></div></form><div class="list" style="margin-top:14px">${fileRows(data.files,id)}</div></aside></section>`;bindLaunch();document.querySelector('#editProject').onclick=()=>projectForm(data.project);document.querySelector('#newNote').onclick=()=>noteForm(id);document.querySelector('#projectFile').onsubmit=async e=>{e.preventDefault();try{await api(`/api/projects/${id}/files`,{method:'POST',body:new FormData(e.target)});toast('Archivo importado');renderProject(id)}catch(error){toast(error.message,'error')}}}catch(error){view.innerHTML=notice(error.message,'bad')}}
function noteForm(projectId){openModal('Nueva nota',`<form id="noteForm"><div class="field"><label>TÍTULO</label><input name="title" required></div><div class="field" style="margin-top:12px"><label>CONTENIDO</label><textarea name="body" class="tall"></textarea></div><div class="form-actions"><button class="btn primary">Guardar</button></div></form>`);document.querySelector('#noteForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/projects/${projectId}/notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();renderProject(projectId)}catch(error){toast(error.message,'error')}}}
function fileRows(files,projectId){return files.map(f=>`<div class="list-row"><div class="list-main"><span class="list-icon">▤</span><div><h4>${esc(f.original_name)}</h4><small>${fmtBytes(f.size)}</small></div></div><div class="form-actions"><a class="btn small" href="/api/files/${f.id}/download">Descargar</a><button class="btn small danger" onclick="deleteFile(${f.id},${projectId})">Eliminar</button></div></div>`).join('')||'<div class="empty">Sin archivos.</div>'}
window.deleteFile=async(id,projectId)=>{if(!confirm('Se creará un respaldo antes de eliminarlo. ¿Continuar?'))return;try{await api(`/api/files/${id}`,{method:'DELETE'});toast('Archivo eliminado con respaldo');renderProject(projectId)}catch(error){toast(error.message,'error')}};

async function renderFiles(){setHead('Archivos','BIBLIOTECA GENERAL');loading('Reuniendo archivos');try{const projects=await api('/api/projects');let files=[];for(const p of projects){const data=await api(`/api/projects/${p.id}`);files.push(...data.files.map(f=>({...f,project:p.name,project_id:p.id})))}view.innerHTML=`<div class="toolbar"><div class="search"><input id="fileSearch" placeholder="Buscar archivo o proyecto"><span>⌕</span></div><button class="btn" data-go="projects">Importar desde un proyecto</button></div><article class="panel"><div class="panel-head"><div><h2>Todos los archivos</h2><p>${files.length} elementos</p></div></div><div id="allFiles" class="list">${globalFileRows(files)}</div></article>`;bindLaunch();document.querySelector('#fileSearch').oninput=e=>document.querySelector('#allFiles').innerHTML=globalFileRows(files.filter(f=>`${f.original_name} ${f.project}`.toLowerCase().includes(e.target.value.toLowerCase())))}catch(error){view.innerHTML=notice(error.message,'bad')}}
function globalFileRows(files){return files.map(f=>`<div class="list-row"><div class="list-main"><span class="list-icon">▤</span><div><h4>${esc(f.original_name)}</h4><small>${esc(f.project)} · ${fmtBytes(f.size)}</small></div></div><div class="form-actions"><a class="btn small" href="/api/files/${f.id}/download">Descargar</a><button class="btn small" onclick="renderProject(${f.project_id})">Proyecto</button></div></div>`).join('')||'<div class="empty"><b>Sin archivos</b>Importa un archivo dentro de un proyecto.</div>'}
window.renderProject=renderProject;

async function renderUpdates(){
  setHead('Actualizaciones','VERSIÓN Y SINCRONIZACIÓN');loading('Comprobando el estado');
  try{
    const [update,sync]=await Promise.all([api('/api/app-update/status'),api('/api/sync/status')]);
    const statusText=update.update_available?'Actualización disponible':update.last_error?'No se pudo comprobar':'La aplicación está actualizada';
    view.innerHTML=`<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Actualización de Dimitry Hub</h2><p>Estado de la aplicación y de su versión publicada.</p></div></div><section class="grid stats-grid" style="grid-template-columns:1fr 1fr">${palEditorFeature('A',update.current_version||'—','Versión instalada')}${palEditorFeature('N',update.latest_version||'Sin comprobar','Última versión')}${palEditorFeature('F',fmtDate(update.checked_at||update.last_checked_at),'Última comprobación')}${palEditorFeature('E',statusText,'Resultado')}</section><div class="form-actions"><button class="btn primary" id="checkAppUpdate">Comprobar la aplicación</button>${update.update_available?'<button class="btn green" id="installAppUpdate">Descargar e instalar</button>':''}</div><div id="updateResult" class="notice ${update.last_error?'info':'info'}">${esc(update.last_error?friendlyConnectionError(update.last_error):statusText)}</div></article><aside class="panel"><div class="panel-head"><div><h2>Fuentes de datos</h2><p>Si una fuente no responde, se conserva automáticamente la última copia válida.</p></div><button class="btn" id="syncAll">Sincronizar datos</button></div><div class="list">${(sync.sources||[]).map(source=>`<div class="list-row"><div><h4>${esc(source.name||source.source_key||'Fuente')}</h4><small>${esc(sourceStatusLabel(source.status))} · ${fmtDate(source.last_checked||source.checked_at||source.updated_at)}</small>${source.error?`<div class="notice info">${esc(friendlyConnectionError(source.error))}</div>`:''}</div></div>`).join('')||'<div class="empty"><b>Sin fuentes configuradas</b>No hay datos externos para mostrar.</div>'}</div></aside></section>`;
    document.querySelector('#checkAppUpdate').onclick=async()=>{const button=document.querySelector('#checkAppUpdate');button.disabled=true;button.textContent='Comprobando…';try{await api('/api/app-update/check',{method:'POST'});toast('Comprobación terminada','ok');await renderUpdates()}catch(error){document.querySelector('#updateResult').className='notice info';document.querySelector('#updateResult').textContent=friendlyConnectionError(error.message);button.disabled=false;button.textContent='Reintentar comprobación'}};
    const install=document.querySelector('#installAppUpdate');if(install)install.onclick=async()=>{install.disabled=true;try{await api('/api/app-update/install',{method:'POST'});toast('Instalador preparado','ok')}catch(error){toast(error.message,'error');install.disabled=false}};
    document.querySelector('#syncAll').onclick=runSync;
  }catch(error){throw error}
}

async function renderSettings(){setHead('Ajustes','DISEÑO, POTENCIA E INTERNET');loading('Cargando ajustes');try{const [settings,status]=await Promise.all([api('/api/settings'),api('/api/ai/status')]);state.settings=settings;state.aiStatus=status;const p=status.providers;view.innerHTML=`<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Apariencia</h2><p>Estilo de consola, lectura clara y controles simples.</p></div></div><div class="grid theme-grid"><button class="theme-card ${settings.theme==='obsidian-gold'?'active':''}" data-theme="obsidian-gold"><div class="theme-preview obsidian"></div><b>Obsidian Gold</b><small>Profesional, fino y elegante</small></button><button class="theme-card ${settings.theme==='arcane-royal'?'active':''}" data-theme="arcane-royal"><div class="theme-preview royal"></div><b>Arcane Royal</b><small>Fantasia ornamental con mármol y amatista</small></button><button class="theme-card ${settings.theme==='midnight-modern'?'active':''}" data-theme="midnight-modern"><div class="theme-preview midnight"></div><b>Midnight Modern</b><small>Modo oscuro actual, limpio y premium</small></button></div><div class="section-head"><div><h3>Fuente de letra</h3><p>Cambia títulos y textos sin afectar documentos exportados.</p></div></div><div class="font-grid"><button class="font-card ${settings.font_style==='console-pop'?'active':''}" data-font="console-pop"><b>Console Pop</b><small>Redondeada y alegre</small></button><button class="font-card ${settings.font_style==='rounded-play'?'active':''}" data-font="rounded-play"><b>Rounded Play</b><small>Suave y estilo consola</small></button><button class="font-card ${settings.font_style==='arcade-pixel'?'active':''}" data-font="arcade-pixel"><b>PIXEL ARCADE</b><small>Retro para títulos</small></button><button class="font-card ${settings.font_style==='study-pro'?'active':''}" data-font="study-pro"><b>Study Pro</b><small>Moderna y académica</small></button></div><label class="check" style="margin-top:14px"><input id="simpleMode" type="checkbox" ${(settings.simple_mode||'1')==='1'?'checked':''}> Modo sencillo: ocultar menús avanzados del lateral</label></article><aside class="panel"><div class="panel-head"><div><h2>Estado de inteligencia</h2><p>El modo automático usa la mejor conexión configurada.</p></div></div><div class="provider-grid"><div class="provider-card ${p.openai.configured?'active':''}"><h4>OpenAI API</h4><p>Alta capacidad y búsqueda web integrada.</p><span class="provider-state">${p.openai.configured?`Conectado · ${esc(p.openai.masked_key)}`:'Sin clave'}</span></div><div class="provider-card ${p.ollama.online?'active':''}"><h4>Ollama local</h4><p>Privado; la potencia depende de tu PC y del modelo.</p><span class="provider-state">${p.ollama.online?`${p.ollama.models.length} modelo(s)`:'No detectado'}</span></div><div class="provider-card ${p.compatible.configured?'active':''}"><h4>Compatible</h4><p>LM Studio, OpenRouter u otro endpoint compatible.</p><span class="provider-state">${p.compatible.configured?'Configurado':'Sin configurar'}</span></div></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>MODO DE IA</label><select id="aiMode"><option value="automatic">Automático</option><option value="local">Solo local</option><option value="cloud">Solo nube</option></select></div><div class="field"><label>PROVEEDOR PREFERIDO</label><select id="aiProvider"><option value="automatic">Elegir automáticamente</option><option value="openai">OpenAI API</option><option value="ollama">Ollama</option><option value="compatible">Compatible</option></select></div><div class="field"><label>RAZONAMIENTO</label><select id="reasoningEffort"><option value="none">Instantáneo</option><option value="low">Rápido</option><option value="medium">Equilibrado</option><option value="high">Profundo</option><option value="xhigh">Muy profundo</option><option value="max">Máximo</option></select></div><div class="field"><label>RAZONAMIENTO OLLAMA</label><select id="ollamaThink"><option value="off">Desactivado</option><option value="low">Bajo</option><option value="medium">Medio</option><option value="high">Alto</option></select></div></div><div class="section-head compact"><div><h3>Perfiles de potencia</h3><p>Elige un perfil y luego guarda los ajustes.</p></div></div><div class="power-presets"><button class="power-preset" data-ai-preset="max"><b>✦ Máxima</b><small>Modelo configurado · razonamiento alto</small></button><button class="power-preset" data-ai-preset="balanced"><b>◈ Equilibrada</b><small>Modelo configurado · razonamiento medio</small></button><button class="power-preset" data-ai-preset="fast"><b>⚡ Rápida</b><small>Modelo configurado · razonamiento bajo</small></button></div><label class="check" style="margin-top:12px"><input id="proMode" type="checkbox" ${(settings.ai_pro_mode||'0')==='1'?'checked':''}> Modo Pro para consultas especialmente difíciles (más lento y con mayor consumo)</label><label class="check" style="margin-top:8px"><input id="fallbackLocal" type="checkbox" ${(settings.ai_fallback_local||'1')==='1'?'checked':''}> Usar Ollama como respaldo si falla la nube</label><label class="check" style="margin-top:8px"><input id="webDefault" type="checkbox" ${(settings.ai_web_search_default||'1')==='1'?'checked':''}> Activar investigación web por defecto en Dimitry AI</label></aside></section><section class="grid two-col" style="margin-top:15px"><article class="panel"><div class="panel-head"><div><h2>OpenAI API</h2><p>Clave protegida con Windows y nunca mostrada completa.</p></div></div><div class="field"><label>CLAVE API</label><div class="key-row"><input id="openaiKey" type="password" placeholder="Pega una nueva clave para guardarla"><button class="btn green" id="saveOpenAIKey">Guardar</button><button class="btn danger" id="clearOpenAIKey">Quitar</button></div></div><div class="field" style="margin-top:12px"><label>MODELO</label><div class="key-row"><select id="openaiModel"><option value="${esc(settings.openai_model||'gpt-5.6')}">${esc(settings.openai_model||'gpt-5.6')}</option></select><button class="btn" id="loadOpenAIModels">Detectar</button></div></div><div class="notice info" style="margin-top:13px">El acceso API se factura por separado. Dimitry Hub no puede usar directamente una suscripción de ChatGPT como credencial.</div></article><aside class="panel"><div class="panel-head"><div><h2>Ollama local</h2><p>Ideal como respaldo y para tareas privadas.</p></div></div><div class="field"><label>DIRECCIÓN</label><input id="ollamaUrl" value="${esc(settings.ollama_url||'http://127.0.0.1:11434')}"></div><div class="field" style="margin-top:12px"><label>MODELO</label><div class="key-row"><select id="ollamaModel"><option value="">Detectando…</option></select><button class="btn" id="detectModels">Detectar</button></div></div><div class="notice info" style="margin-top:13px">Los modelos locales grandes necesitan bastante RAM o VRAM. El programa puede funcionar con modelos pequeños, pero la calidad no será idéntica a un servicio de nube avanzado.</div></aside></section><section class="grid two-col" style="margin-top:15px"><article class="panel"><div class="panel-head"><div><h2>Proveedor compatible</h2><p>Endpoint con formato OpenAI Chat Completions.</p></div></div><div class="field"><label>URL BASE, INCLUYENDO /v1</label><input id="compatibleBase" value="${esc(settings.compatible_base_url||'')}" placeholder="http://127.0.0.1:1234/v1"></div><div class="field" style="margin-top:12px"><label>CLAVE OPCIONAL</label><div class="key-row"><input id="compatibleKey" type="password" placeholder="Clave del proveedor"><button class="btn green" id="saveCompatibleKey">Guardar</button><button class="btn danger" id="clearCompatibleKey">Quitar</button></div></div><label class="check" style="margin-top:10px"><input id="compatibleNoKey" type="checkbox" ${(settings.compatible_no_key||'0')==='1'?'checked':''}> Este servidor local no requiere clave</label><div class="field" style="margin-top:12px"><label>MODELO</label><div class="key-row"><select id="compatibleModel"><option value="${esc(settings.compatible_model||'')}">${esc(settings.compatible_model||'Seleccionar')}</option></select><button class="btn" id="loadCompatibleModels">Detectar</button></div></div></article><aside class="panel"><div class="panel-head"><div><h2>Internet y actualizaciones</h2></div></div><div class="form-grid"><div class="field"><label>MODO</label><select id="syncMode"><option value="manual">Manual</option><option value="safe">Automático seguro</option><option value="auto">Automático</option></select></div><div class="field"><label>REVISAR CADA</label><select id="syncHours"><option value="6">6 horas</option><option value="12">12 horas</option><option value="24">24 horas</option><option value="48">48 horas</option><option value="168">7 días</option></select></div><div class="field full"><label>REPOSITORIO DEL EDITOR PALWORLD</label><input id="palRepo" value="${esc(settings.palworld_repo_url||'https://github.com/oMaN-Rod/palworld-save-pal')}"></div><div class="field full"><label>CORREO PARA CROSSREF (OPCIONAL)</label><input id="crossrefEmail" type="email" value="${esc(settings.crossref_email||'')}"></div><div class="field full"><label>NOMBRE MOSTRADO</label><input id="displayName" value="${esc(settings.display_name||'Dimitry')}"></div></div><label class="check" style="margin-top:10px"><input id="syncStartup" type="checkbox" ${(settings.sync_on_startup||'1')==='1'?'checked':''}> Revisar fuentes al abrir</label><div class="form-actions"><button class="btn primary" id="saveSettings">Guardar todos los ajustes</button></div><div class="notice info" style="margin-top:14px">Las bibliotecas y metadatos pueden actualizarse automáticamente. Los saves y programas descargados siguen requiriendo una acción explícita.</div></aside></section>`;document.querySelector('#aiMode').value=settings.ai_mode||'automatic';document.querySelector('#aiProvider').value=settings.ai_provider||'automatic';document.querySelector('#reasoningEffort').value=settings.ai_reasoning_effort||'medium';document.querySelector('#ollamaThink').value=settings.ollama_think||'off';document.querySelector('#syncMode').value=settings.auto_sync_mode||'safe';document.querySelector('#syncHours').value=settings.auto_sync_interval_hours||'24';document.querySelectorAll('.theme-card[data-theme]').forEach(b=>b.onclick=()=>applyTheme(b.dataset.theme));document.querySelectorAll('.font-card[data-font]').forEach(b=>b.onclick=()=>applyFont(b.dataset.font));document.querySelectorAll('[data-ai-preset]').forEach(b=>b.onclick=()=>applyAIPreset(b.dataset.aiPreset));document.querySelector('#detectModels').onclick=()=>loadModels(true);document.querySelector('#loadOpenAIModels').onclick=()=>loadCloudModels('openai');document.querySelector('#loadCompatibleModels').onclick=()=>loadCloudModels('compatible');document.querySelector('#saveOpenAIKey').onclick=()=>saveAISecret('openai','#openaiKey');document.querySelector('#clearOpenAIKey').onclick=()=>clearAISecret('openai');document.querySelector('#saveCompatibleKey').onclick=()=>saveAISecret('compatible','#compatibleKey');document.querySelector('#clearCompatibleKey').onclick=()=>clearAISecret('compatible');document.querySelector('#saveSettings').onclick=saveSettings;await loadModels(false)}catch(error){view.innerHTML=notice(error.message,'bad')}}
async function applyTheme(theme){document.body.dataset.theme=theme;state.settings.theme=theme;document.querySelectorAll('.theme-card[data-theme]').forEach(b=>b.classList.toggle('active',b.dataset.theme===theme));await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({theme})});toast('Tema aplicado')}
async function applyFont(font){document.body.dataset.font=font;state.settings.font_style=font;document.querySelectorAll('.font-card[data-font]').forEach(b=>b.classList.toggle('active',b.dataset.font===font));await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({font_style:font})});toast('Tipografía aplicada')}
function applyAIPreset(profile){const ready=state.aiStatus?.providers?.openai?.configured||state.aiStatus?.providers?.ollama?.online||state.aiStatus?.providers?.compatible?.configured;if(!ready){toast('Configura primero OpenAI, Ollama o un proveedor compatible','error');return}const profiles={max:{effort:'high',pro:true,label:'Máxima'},balanced:{effort:'medium',pro:false,label:'Equilibrada'},fast:{effort:'low',pro:false,label:'Rápida'}};const item=profiles[profile];if(!item)return;document.querySelector('#reasoningEffort').value=item.effort;document.querySelector('#proMode').checked=item.pro;document.querySelectorAll('[data-ai-preset]').forEach(b=>b.classList.toggle('active',b.dataset.aiPreset===profile));toast(`Perfil ${item.label} seleccionado. Pulsa Guardar todos los ajustes.`)}
async function loadModels(show=true){const select=document.querySelector('#ollamaModel');if(!select)return;try{const data=await api('/api/ai/models/ollama');const models=data.models||[];select.innerHTML=models.length?models.map(m=>`<option value="${esc(m.name||m.model)}">${esc(m.name||m.model)}${m.details?.parameter_size?` · ${esc(m.details.parameter_size)}`:''}</option>`).join(''):'<option value="">Ollama no detectado</option>';if(state.settings.ollama_model)select.value=state.settings.ollama_model;if(show)toast(models.length?`${models.length} modelo(s) encontrado(s)`:'No se detectó Ollama',models.length?'ok':'error')}catch(error){toast(error.message,'error')}}
async function loadCloudModels(provider){const select=document.querySelector(provider==='openai'?'#openaiModel':'#compatibleModel');const button=document.querySelector(provider==='openai'?'#loadOpenAIModels':'#loadCompatibleModels');button.disabled=true;try{if(provider==='compatible')await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({compatible_base_url:val('#compatibleBase'),compatible_no_key:bool('#compatibleNoKey')?'1':'0'})});const data=await api(`/api/ai/models/${provider}`);const models=data.models||[];select.innerHTML=models.length?models.map(m=>`<option value="${esc(m.id||m.name)}">${esc(m.id||m.name)}</option>`).join(''):'<option value="">No se encontraron modelos</option>';const current=provider==='openai'?state.settings.openai_model:state.settings.compatible_model;if(current)select.value=current;toast(`${models.length} modelo(s) detectado(s)`,models.length?'ok':'error')}catch(error){toast(error.message,'error')}finally{button.disabled=false}}
async function saveAISecret(provider,selector){const api_key=val(selector);if(!api_key){toast('Pega una clave primero','error');return}try{await api('/api/ai/secret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,api_key})});document.querySelector(selector).value='';toast('Credencial guardada de forma protegida');renderSettings()}catch(error){toast(error.message,'error')}}
async function clearAISecret(provider){if(!confirm('¿Quitar esta credencial del equipo?'))return;try{await api(`/api/ai/secret/${provider}`,{method:'DELETE'});toast('Credencial eliminada');renderSettings()}catch(error){toast(error.message,'error')}}
async function saveSettings(){const payload={theme:state.settings.theme||'obsidian-gold',font_style:state.settings.font_style||'console-pop',simple_mode:bool('#simpleMode')?'1':'0',ollama_url:val('#ollamaUrl'),ollama_model:val('#ollamaModel'),ollama_think:val('#ollamaThink'),display_name:val('#displayName')||'Dimitry',palworld_repo_url:val('#palRepo'),auto_sync_mode:val('#syncMode'),auto_sync_interval_hours:val('#syncHours'),sync_on_startup:bool('#syncStartup')?'1':'0',crossref_email:val('#crossrefEmail'),internet_enabled:'1',ai_mode:val('#aiMode'),ai_provider:val('#aiProvider'),ai_fallback_local:bool('#fallbackLocal')?'1':'0',ai_web_search_default:bool('#webDefault')?'1':'0',ai_reasoning_effort:val('#reasoningEffort'),ai_pro_mode:bool('#proMode')?'1':'0',openai_model:val('#openaiModel')||state.settings.openai_model||'gpt-5.6',compatible_base_url:val('#compatibleBase'),compatible_model:val('#compatibleModel'),compatible_no_key:bool('#compatibleNoKey')?'1':'0'};try{state.settings=await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});document.body.dataset.simple=state.settings.simple_mode||'1';setAvatar();toast('Ajustes guardados')}catch(error){toast(error.message,'error')}}
function setAvatar(){const name=state.settings.display_name||'Dimitry';document.querySelector('#profileChip').textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}

async function openProfilePanel(){try{const [ai,update]=await Promise.all([api('/api/ai/status'),api('/api/app-update/status')]);const ready=ai.providers?.openai?.configured||ai.providers?.ollama?.online||ai.providers?.compatible?.configured;const name=state.settings.display_name||'Dimitry';openModal('Perfil y control rápido',`<div class="profile-summary"><div class="avatar" style="display:grid;place-items:center;margin-bottom:12px">${esc(name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</div><h3>${esc(name)}</h3><p>Dimitry Hub ${esc(update.current_version||'')}</p></div><div class="notice ${ready?'info':'bad'}">${ready?'Dimitry AI está preparada.':'Dimitry AI todavía no tiene ningún proveedor configurado.'}</div><div class="form-actions"><button class="btn primary" id="profileAI">${ready?'Abrir Dimitry AI':'Configurar IA'}</button><button class="btn" id="profileUpdates">Actualizaciones</button><button class="btn danger" id="profileCloseApp">Cerrar Dimitry Hub</button></div>`);document.querySelector('#profileAI').onclick=()=>{closeModal();navigate(ready?'assistant':'settings')};document.querySelector('#profileUpdates').onclick=()=>{closeModal();navigate('updates')};document.querySelector('#profileCloseApp').onclick=shutdownApp}catch(error){toast(error.message,'error')}}
async function shutdownApp(){const button=document.querySelector('#profileCloseApp');if(button)button.disabled=true;try{await api('/api/system/shutdown',{method:'POST'});document.querySelector('#modalBody').innerHTML='<div class="notice info"><b>Dimitry Hub se está cerrando.</b><br>Ya puedes cerrar esta pestaña o ejecutar el instalador.</div>'}catch(error){toast(error.message,'error');if(button)button.disabled=false}}
function renderLegal(){
  setHead('Escritos jurídicos','ESTUDIO');
  view.innerHTML=`${studyTabs('legal')}<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Documento jurídico peruano</h2><p>Genera escritos y actas editables sin inventar normas, autoridades ni datos personales.</p></div></div><div class="form-grid"><div class="field"><label>TIPO DE DOCUMENTO</label><select id="legalKind"><option value="solicitud">Solicitud administrativa</option><option value="carta_notarial">Carta notarial</option><option value="apersonamiento">Apersonamiento</option><option value="reconsideracion">Recurso de reconsideración</option><option value="apelacion">Recurso de apelación</option><option value="denuncia">Denuncia</option><option value="descargo">Escrito de descargo</option><option value="poder_simple">Carta poder simple</option><option value="acta_reunion">Acta de reunión</option></select></div><div class="field"><label id="legalAuthorityLabel">AUTORIDAD O DESTINATARIO</label><input id="legalAuthority"></div><div class="field"><label id="legalNameLabel">NOMBRE COMPLETO</label><input id="legalName"></div><div class="field" id="legalDniField"><label>DNI (8 DÍGITOS)</label><input id="legalDni" inputmode="numeric" maxlength="8"></div><div class="field full"><label id="legalAddressLabel">DOMICILIO PROCESAL O REAL</label><input id="legalAddress"></div><div class="field"><label>CIUDAD Y FECHA</label><input id="legalCityDate" placeholder="Abancay, 1 de agosto de 2026"></div><div class="field" id="legalTimeField" hidden><label>HORA</label><input id="legalTime" placeholder="10:00 a. m."></div><div class="field full"><label id="legalSummaryLabel">SUMILLA</label><input id="legalSummary" placeholder="Resumen breve de lo solicitado"></div><div class="field full" id="legalParticipantsField" hidden><label>PARTICIPANTES (UNO POR LÍNEA)</label><textarea id="legalParticipants"></textarea></div><div class="field full"><label id="legalRequestLabel">PETITORIO</label><textarea id="legalRequest"></textarea></div><div class="field full"><label id="legalFactsLabel">HECHOS EN ORDEN CRONOLÓGICO</label><textarea id="legalFacts" class="tall"></textarea></div><div class="field full"><label id="legalBasisLabel">FUNDAMENTO LEGAL VERIFICADO (OPCIONAL)</label><textarea id="legalBasis"></textarea></div><div class="field full"><label id="legalEvidenceLabel">MEDIOS PROBATORIOS Y ANEXOS (OPCIONAL)</label><textarea id="legalEvidence"></textarea></div></div><label class="check" style="margin-top:13px"><input id="legalWeb" type="checkbox"> Verificar únicamente en fuentes oficiales peruanas disponibles</label><div class="form-actions"><button class="btn yellow" id="createLegal">Crear Word editable</button></div><div id="legalResult"></div></article><aside class="panel"><div class="notice bad">Borrador para revisión profesional. Antes de presentarlo verifica competencia, vía, plazo, firma, tasas, copias, anexos y vigencia de cada norma.</div><div class="section-head"><div><h3>Control previo</h3></div></div><div class="list"><div class="list-row"><div><h4>Datos completos</h4><small>Identidad, destinatario o entidad, domicilio o lugar, fecha y objeto.</small></div></div><div class="list-row"><div><h4>Fundamento verificable</h4><small>No se incorpora ningún artículo no aportado o confirmado.</small></div></div><div class="list-row"><div><h4>Firmas y anexos</h4><small>Comprueba participantes, acuerdos, anexos y firmas antes de usar el documento.</small></div></div></div></aside></section>`;
  bindStudyTabs();document.querySelector('#legalKind').onchange=updateLegalForm;document.querySelector('#createLegal').onclick=createLegal;updateLegalForm();
}

function updateLegalForm(){
  const kind=val('#legalKind'),isMinutes=kind==='acta_reunion',isPower=kind==='poder_simple',isLetter=kind==='carta_notarial';
  if(!document.querySelector('#legalProxyFields'))document.querySelector('#legalParticipantsField').insertAdjacentHTML('afterend','<div class="field full" id="legalProxyFields" style="display:none"><div class="form-grid"><div class="field"><label>NOMBRE DE LA PERSONA APODERADA</label><input id="legalProxyName"></div><div class="field"><label>DNI DE LA PERSONA APODERADA</label><input id="legalProxyDni" inputmode="numeric" maxlength="8"></div></div></div>');
  document.querySelector('#legalDniField').style.display=isMinutes?'none':'';
  document.querySelector('#legalTimeField').style.display=isMinutes?'':'none';
  document.querySelector('#legalParticipantsField').style.display=isMinutes?'':'none';
  document.querySelector('#legalProxyFields').style.display=isPower?'block':'none';
  document.querySelector('#legalAuthorityLabel').textContent=isMinutes?'ENTIDAD U ORGANIZACIÓN':'AUTORIDAD O DESTINATARIO';
  document.querySelector('#legalNameLabel').textContent=isMinutes?'RESPONSABLE DE LA REUNIÓN':(isPower?'NOMBRE DE LA PERSONA OTORGANTE':'NOMBRE COMPLETO');
  document.querySelector('#legalAddressLabel').textContent=isMinutes?'LUGAR DE LA REUNIÓN':'DOMICILIO PROCESAL O REAL';
  document.querySelector('#legalSummaryLabel').textContent=isMinutes?'OBJETO DE LA REUNIÓN':'SUMILLA';
  document.querySelector('#legalRequestLabel').textContent=isMinutes?'AGENDA':(isPower?'ALCANCE DEL PODER':(isLetter?'REQUERIMIENTO':'PETITORIO'));
  document.querySelector('#legalFactsLabel').textContent=isMinutes?'DESARROLLO DE LA REUNIÓN':(isPower?'FACULTADES OTORGADAS':(isLetter?'ANTECEDENTES':'HECHOS EN ORDEN CRONOLÓGICO'));
  document.querySelector('#legalBasisLabel').textContent=isMinutes?'BASE LEGAL O DOCUMENTAL (OPCIONAL)':'FUNDAMENTO LEGAL VERIFICADO (OPCIONAL)';
  document.querySelector('#legalEvidenceLabel').textContent=isMinutes?'ACUERDOS':((isPower||isLetter)?'DOCUMENTOS QUE SE ACOMPAÑAN (OPCIONAL)':'MEDIOS PROBATORIOS Y ANEXOS (OPCIONAL)');
}

async function createLegal(){
  const kind=val('#legalKind'),isMinutes=kind==='acta_reunion',isPower=kind==='poder_simple',facts=val('#legalFacts'),request_text=val('#legalRequest'),dni=val('#legalDni'),evidence=val('#legalEvidence');
  const required=[['#legalAuthority','la autoridad o entidad'],['#legalName','el nombre responsable'],['#legalAddress','el domicilio o lugar'],['#legalCityDate','la ciudad y fecha'],['#legalSummary','la sumilla u objeto']];
  const missing=required.filter(([selector])=>!val(selector)).map(([,label])=>label);
  if(!request_text)missing.push(isMinutes?'la agenda':'el petitorio');if(!facts)missing.push(isMinutes?'el desarrollo':'los hechos');
  if(isMinutes&&!val('#legalParticipants'))missing.push('los participantes');if(isMinutes&&!evidence)missing.push('los acuerdos');
  if(!isMinutes&&!/^\d{8}$/.test(dni))missing.push('un DNI válido de ocho dígitos');
  if(isPower&&!val('#legalProxyName'))missing.push('el nombre de la persona apoderada');if(isPower&&!/^\d{8}$/.test(val('#legalProxyDni')))missing.push('un DNI válido de la persona apoderada');
  if(missing.length){toast(`Completa ${missing.join(', ')}`,'error');return}
  const out=document.querySelector('#legalResult');out.innerHTML='<div class="result">Redactando…</div>';
  const fields={authority:val('#legalAuthority'),applicant:val('#legalName'),dni,address:val('#legalAddress'),city_date:val('#legalCityDate'),time:val('#legalTime'),sumilla:val('#legalSummary'),participants:val('#legalParticipants'),proxy_name:val('#legalProxyName'),proxy_dni:val('#legalProxyDni')};
  try{const data=await api('/api/legal/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,fields,facts,legal_basis:val('#legalBasis'),evidence,request_text,use_ai:true,verify_web:bool('#legalWeb')})});out.innerHTML=`<div class="result">${data.warning?notice(data.warning,'info'):''}${data.provider?`<p><b>Motor:</b> ${esc(aiProviderLabel(data.provider))} · ${esc(data.model||'')}</p>`:''}${sourcePills(data.sources||[])}<div class="form-actions"><a class="btn blue" href="${data.download_url}">Descargar ${esc(data.filename)}</a></div><pre>${esc(data.draft)}</pre></div>`;toast('Documento creado')}catch(error){out.innerHTML=notice(error.message,'bad');toast(error.message,'error')}
}

function bindGlobal(){
  document.addEventListener('click',event=>{
    const target=event.target.closest('[data-route]');
    if(!target)return;
    event.preventDefault();
    navigate(target.dataset.route);
  });
  document.querySelector('#menuBtn').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
  document.querySelector('#modalClose').onclick=closeModal;
  modal.onclick=e=>{if(e.target===modal)closeModal()};
  document.querySelector('#quickSync').onclick=runSync;
  document.querySelector('#profileChip').onclick=openProfilePanel;
}
async function boot(){bindGlobal();try{state.settings=await api('/api/settings');document.body.dataset.theme=state.settings.theme||'obsidian-gold';document.body.dataset.font=state.settings.font_style||'console-pop';document.body.dataset.simple=state.settings.simple_mode||'1';setAvatar()}catch{}navigate('home')}
boot();
